'use strict';
const KEY='voyager_studio_test_v2', VERSION=1;
const blank=()=>({schema:VERSION,trips:[],days:[],bookings:[],expenses:[],packing:[],journal:[],vault:[],rates:{EUR:1},settings:{theme:'system'}});
let db;try{db=JSON.parse(localStorage.getItem(KEY))||blank()}catch{db=blank()}if(!db||!Array.isArray(db.trips))db=blank();for(const k of ['days','bookings','expenses','packing','journal','vault'])if(!Array.isArray(db[k]))db[k]=[];db.rates ||= {EUR:1};db.settings ||= {theme:'system'};
let tab='dashboard', tripId=db.trips[0]?.id||'', vaultUnlocked=null;
let $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), id=()=>crypto.randomUUID?crypto.randomUUID():[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,'0')).join(''), now=()=>new Date().toISOString().slice(0,10), money=(n,c='EUR')=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:c}).format(Number(n)||0), date=x=>x?new Date(x+'T12:00:00').toLocaleDateString('fr-FR'):'—', toast=s=>{const e=$('#toast');e.textContent=s;e.style.display='block';setTimeout(()=>e.style.display='none',2600)}, save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch{alert('Stockage saturé. Exportez une sauvegarde JSON et réduisez les pièces jointes.');return false}}, trip=()=>db.trips.find(x=>x.id===tripId), related=k=>db[k].filter(x=>x.tripId===tripId), btn=(txt,act,cls='')=>`<button class="${cls}" data-action="${act}">${txt}</button>`, box=(title,content)=>`<section class="card"><h2>${title}</h2>${content}</section>`, field=(name,label,type='text',value='',extra='')=>`<div><label for="f_${name}">${label}</label><input id="f_${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`, area=(name,label,value='')=>`<div><label for="f_${name}">${label}</label><textarea id="f_${name}" name="${name}">${esc(value)}</textarea></div>`, select=(name,label,opts,value='')=>`<div><label for="f_${name}">${label}</label><select id="f_${name}" name="${name}">${opts.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`, action=(a,i)=>`<div class="row">${btn('Modifier',`edit:${a}:${i}`)}${btn('Supprimer',`del:${a}:${i}`,'danger')}</div>`;
const titles={dashboard:['Vue d’ensemble','Tous vos voyages en un seul endroit.'],trips:['Mes voyages','Voyages solo ou en groupe, modèles et archives.'],days:['Itinéraire','Journées, étapes et transports réorganisables.'],bookings:['Réservations','Transports, hébergements et confirmations.'],budget:['Budget multidevise','Dépenses, conversions et enveloppes.'],maps:['Cartes et traces','GPX hors ligne, sans fond topographique automatique.'],packing:['Bagages','Listes, quantités et import MY GEAR.'],vault:['Coffre documentaire','Documents chiffrés localement avec votre phrase secrète.'],journal:['Journal et souvenirs','Notes, photos et export imprimable.'],share:['Partage et échanges','Exports lisibles et interopérabilité manuelle.'],data:['Données et sauvegardes','Sauvegardes versionnées et restauration contrôlée.']};
function choose(){return `<div class="card row"><label for="tripSelect">Voyage actif</label><select id="tripSelect" style="flex:1;min-width:180px">${db.trips.map(t=>`<option value="${t.id}" ${t.id===tripId?'selected':''}>${esc(t.name)}</option>`).join('')}</select>${btn('+ Voyage','new:trips','primary')}</div>`}
function render(){document.body.classList.toggle('light',db.settings.theme==='light');$('#pageTitle').textContent=titles[tab][0];$('#subtitle').textContent=titles[tab][1];$('#tabs').innerHTML=Object.keys(titles).map(k=>`<button data-tab="${k}" class="${tab===k?'active':''}">${({dashboard:'Accueil',trips:'Voyages',days:'Itinéraire',bookings:'Réservations',budget:'Budget',maps:'Cartes',packing:'Bagages',vault:'Coffre',journal:'Journal',share:'Partage',data:'Données'})[k]}</button>`).join('');let content='';if(!['dashboard','trips','data'].includes(tab)&&db.trips.length)content+=choose();if(!db.trips.length&&!['trips','data'].includes(tab))content+=box('Commencer',`Créez votre premier voyage pour utiliser les modules. ${btn('Créer un voyage','new:trips','primary')}`);else content+=({dashboard:dashboard,trips:trips,days:days,bookings:bookings,budget:budget,maps:maps,packing:packing,vault:vault,journal:journal,share:share,data:dataView})[tab]();$('#view').innerHTML=content}
function dashboard(){const upcoming=db.bookings.filter(b=>b.tripId===tripId&&b.start>=now()).sort((a,b)=>a.start.localeCompare(b.start)).slice(0,4), total=related('expenses').reduce((a,e)=>a+eur(e),0);return `<div class="grid">${[['Voyages',db.trips.length],['Journées',related('days').length],['Réservations',related('bookings').length],['Dépenses (EUR)',money(total)]].map(([n,v])=>`<div class="card"><div class="muted">${n}</div><div class="stat">${v}</div></div>`).join('')}</div>${box('Voyage actif',trip()?`<h3>${esc(trip().name)}</h3><p>${esc(trip().destination)} · ${date(trip().start)} → ${date(trip().end)} · ${esc(trip().mode||'solo')}</p><div class="notice">${esc(trip().notes||'Aucune note pour ce voyage.')}</div>`:'Aucun voyage actif.')}${box('Prochaines réservations',upcoming.length?upcoming.map(b=>`<div class="item"><strong>${esc(b.name)}</strong><p>${date(b.start)} · ${esc(b.type)} · ${esc(b.reference||'Sans référence')}</p></div>`).join(''):'Aucune réservation future enregistrée.')}`}
function trips(){return box('Voyages',`${btn('+ Nouveau voyage','new:trips','primary')}<div class="stack">${db.trips.map(t=>`<div class="item"><div class="row between"><h3>${esc(t.name)}</h3><span class="pill">${esc(t.status)}</span></div><p>${esc(t.destination)} · ${date(t.start)} → ${date(t.end)} · ${esc(t.mode)}</p><div class="row">${btn('Ouvrir',`open:${t.id}`,'primary')}${btn('Dupliquer',`duplicate:${t.id}`)}${action('trips',t.id)}</div></div>`).join('')||'<p>Aucun voyage.</p>'}</div>`)}
function days(){return box('Journées et trajets',`${btn('+ Journée / trajet','new:days','primary')}<p class="small">Ordre modifiable avec les flèches. Les déplacements sont enregistrés comme étapes.</p>${related('days').sort((a,b)=>(a.order||0)-(b.order||0)).map((d,i)=>`<div class="item"><div class="row between"><h3>${esc(d.title)}</h3><span class="pill">${date(d.day)}</span></div><p>${esc(d.kind)} · ${esc(d.from||'')} ${d.to?'→ '+esc(d.to):''}</p><p>${esc(d.notes||'')}</p><div class="row">${btn('↑',`move:${d.id}:-1`)}${btn('↓',`move:${d.id}:1`)}${action('days',d.id)}</div></div>`).join('')||'<p>Ajoutez vos journées et transferts.</p>'}`)}
function bookings(){return box('Réservations et confirmations',`${btn('+ Réservation','new:bookings','primary')}<p class="small">Vous pouvez joindre un fichier de confirmation dans la fiche (taille limitée par le stockage local).</p>${related('bookings').sort((a,b)=>a.start.localeCompare(b.start)).map(b=>`<div class="item"><div class="row between"><h3>${esc(b.name)}</h3><span class="pill">${esc(b.type)}</span></div><p>${date(b.start)} ${esc(b.time||'')} · ${esc(b.place||'')}</p><p>Référence : ${esc(b.reference||'—')} · ${money(b.cost,b.currency)}</p>${b.attachment?btn('Télécharger le justificatif',`attachment:${b.id}`):''}${action('bookings',b.id)}</div>`).join('')||'<p>Aucune réservation.</p>'}`)}
function eur(e){const r=Number(db.rates[e.currency]);return Number.isFinite(r)&&r>0?Number(e.amount)*r:0}
function budget(){
 const es=related('expenses'), bs=related('bookings').filter(b=>Number(b.cost)>0), linked=new Set(es.map(e=>e.bookingId).filter(Boolean));
 const bookingsToCount=bs.filter(b=>!linked.has(b.id));
 const spent=es.reduce((a,e)=>a+eur(e),0), reserved=bookingsToCount.reduce((a,b)=>a+eur({amount:b.cost,currency:b.currency||'EUR'}),0);
 const cap=Number(trip()?.budget||0), total=spent+reserved;
 const reservationItems=bs.map(b=>`<div class="item"><div class="row between"><strong>${esc(b.name)}</strong><strong>${money(b.cost,b.currency||'EUR')}</strong></div><p>${esc(b.type)} · ${date(b.start)} · ≈ ${money(eur({amount:b.cost,currency:b.currency||'EUR'}))}${linked.has(b.id)?' · Déjà comptabilisée dans les dépenses':''}</p></div>`).join('');
 return `${box('Budget global du voyage',`<form id="tripBudgetForm" class="fields">${field('budget','Budget prévu (EUR)','number',trip()?.budget??'','min="0" step="0.01" required')}<div><button class="primary">Enregistrer le budget</button></div></form><p class="small">Le montant est aussi disponible dans la fiche Voyage. Les deux vues restent synchronisées.</p>`)}
 <div class="grid"><div class="card"><div class="muted">Dépenses manuelles (EUR)</div><div class="stat">${money(spent)}</div></div><div class="card"><div class="muted">Réservations non liées (EUR)</div><div class="stat">${money(reserved)}</div></div><div class="card"><div class="muted">Total engagé (EUR)</div><div class="stat">${money(total)}</div></div><div class="card"><div class="muted">Budget restant (EUR)</div><div class="stat">${trip()?.budget!==''&&trip()?.budget!=null?money(cap-total):'Non défini'}</div></div></div>
 ${box('Réservations du voyage',`<p class="small">Les réservations payantes sont reprises automatiquement ici et recalculées si vous les modifiez ou les supprimez. Une dépense liée à une réservation n’est pas comptée deux fois.</p>${reservationItems||'<p>Aucune réservation avec montant.</p>'}`)}
 ${box('Dépenses',`${btn('+ Dépense','new:expenses','primary')}${es.map(e=>`<div class="item"><div class="row between"><strong>${esc(e.name)}</strong><strong>${money(e.amount,e.currency)}</strong></div><p>${date(e.day)} · ${esc(e.category)} · ≈ ${money(eur(e))}${e.bookingId?' · Réservation liée':''}</p>${action('expenses',e.id)}</div>`).join('')||'<p>Aucune dépense.</p>'}`)}
 ${box('Taux de conversion manuels',`<p class="small">Montant en EUR pour 1 unité de devise. Valeurs indicatives, à actualiser vous-même. Aucun taux en direct.</p><form id="ratesForm" class="fields">${['EUR','USD','GBP','CHF','JPY'].map(c=>field(c,c+' → EUR','number',db.rates[c]??'', 'min="0.000001" step="any"')).join('')}<div><button class="primary">Enregistrer les taux</button></div></form>`)}`;
}
let lastGPXSegments=[];
function parseGPX(xml){const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror'))throw Error('GPX XML invalide');const read=n=>{const lat=n.getAttribute('lat'),lon=n.getAttribute('lon'),p=[Number(lat),Number(lon)];if(lat===null||lon===null||!p.every(Number.isFinite)||Math.abs(p[0])>90||Math.abs(p[1])>180)throw Error('Coordonnées GPX invalides');return p};let segments=[...doc.querySelectorAll('trkseg,rte')].map(n=>[...n.querySelectorAll('trkpt,rtept')].map(read)).filter(x=>x.length);if(!segments.length)segments=[[...doc.querySelectorAll('trkpt,rtept')].map(read)];const pts=segments.flat();if(pts.length<2)throw Error('Deux points GPX minimum');if(pts.length>20000)throw Error('GPX trop volumineux : maximum 20 000 points, aucun point importé');lastGPXSegments=segments;return pts}
function svgMap(points){if(!points?.length)return '<p>Aucune trace importée.</p>';let minX=Math.min(...points.map(p=>p[1])),maxX=Math.max(...points.map(p=>p[1])),minY=Math.min(...points.map(p=>p[0])),maxY=Math.max(...points.map(p=>p[0]));const sx=x=>20+560*(x-minX)/Math.max(maxX-minX,.00001),sy=y=>20+320*(maxY-y)/Math.max(maxY-minY,.00001);return `<svg viewBox="0 0 600 360" role="img" aria-label="Tracé GPX vectoriel sans fond de carte">${(trip()?.gpx===points&&trip()?.gpxSegments?.length?trip().gpxSegments:[points]).map(segment=>`<polyline fill="none" stroke="#16b8d1" stroke-width="3" points="${segment.map(p=>`${sx(p[1]).toFixed(1)},${sy(p[0]).toFixed(1)}`).join(' ')}"/>`).join('')}<circle cx="${sx(points[0][1])}" cy="${sy(points[0][0])}" r="6" fill="#fff"/></svg><p class="small">${points.length} points · Affichage vectoriel hors ligne, sans fond cartographique.</p>`}
function maps(){return box('Traces GPX',`<label>Importer une trace GPX</label><input id="gpxInput" type="file" accept=".gpx,application/gpx+xml,text/xml"><div class="row">${btn('Exporter GPX','export:gpx')}${btn('Supprimer la trace','clear:gpx','danger')}</div><div class="map">${svgMap(trip()?.gpx)}</div><div class="notice">Ce tracé ne constitue pas une carte topographique. Vérifiez toujours l'itinéraire avec des sources officielles et des outils de navigation indépendants.</div>`)}
function packing(){const list=related('packing'),checked=list.filter(x=>x.ready).length;return box('Bagages et préparation',`<div class="stat">${checked}/${list.length} prêts</div><div class="progress"><div style="width:${list.length?checked/list.length*100:0}%"></div></div><div class="row">${btn('+ Article','new:packing','primary')}<label class="btn">Importer CSV MY GEAR<input id="gearInput" type="file" accept=".csv,text/csv" hidden></label></div>${list.map(p=>`<div class="item"><div class="row between"><label><input type="checkbox" data-ready="${p.id}" ${p.ready?'checked':''}> ${esc(p.name)} · ×${Number(p.qty)||1}</label><span>${p.weightUnknown?'Poids non renseigné':(Number(p.grams)||0)+' g/unité'}</span></div>${action('packing',p.id)}</div>`).join('')||'<p>Aucun article.</p>'}<p>Poids total connu : <strong>${(list.reduce((a,p)=>a+(Number(p.grams)||0)*(Number(p.qty)||1),0)/1000).toLocaleString('fr-FR')} kg</strong></p>`)}
function journal(){return box('Journal et souvenirs',`${btn('+ Souvenir','new:journal','primary')}${btn('Exporter / imprimer en PDF','print:journal')}${related('journal').sort((a,b)=>b.day.localeCompare(a.day)).map(j=>`<div class="item"><h3>${esc(j.title)}</h3><p>${date(j.day)} · ${esc(j.place||'')}</p><p>${esc(j.notes)}</p>${j.photo?`<img src="${j.photo}" alt="Souvenir" style="max-width:100%;max-height:260px;border-radius:12px">`:''}${action('journal',j.id)}</div>`).join('')||'<p>Votre carnet est vide.</p>'}`)}
function vault(){return box('Coffre chiffré',`<div class="notice">Le contenu est chiffré avec AES-GCM et une clé dérivée de votre phrase secrète (PBKDF2). Phrase perdue = document irrécupérable. Aucun serveur ne stocke votre clé.</div><label>Phrase secrète du coffre</label><input type="password" id="vaultPass" autocomplete="off" placeholder="Phrase secrète"><div class="row">${btn('Déverrouiller','unlock:vault','primary')}${btn('Verrouiller','lock:vault')}</div>${vaultUnlocked?`<div class="row">${btn('+ Document','new:vault','primary')}</div>${related('vault').map(v=>`<div class="item"><strong>${esc(v.name)}</strong><p>${date(v.day)} · Document chiffré</p><div class="row">${btn('Ouvrir','openvault:'+v.id)}${btn('Supprimer','del:vault:'+v.id,'danger')}</div></div>`).join('')||'<p>Aucun document chiffré.</p>'}`:'<p>Déverrouillez le coffre pour voir les documents.</p>'}`)}
function share(){return box('Échanges et partage',`<p>Partage en lecture seule : exportez une page HTML autonome contenant le résumé du voyage. Elle ne donne aucun accès à votre base locale.</p><div class="row">${btn('Exporter résumé HTML','export:html','primary')}${btn('Exporter itinéraire CSV','export:days')}${btn('Exporter bagages CSV','export:packing')}${btn('Exporter dépenses CSV','export:expenses')}${btn('Exporter GPX','export:gpx')}${btn('Exporter calendrier ICS','export:ics')}</div><div class="notice">MY GEAR et TRAIL COMMAND : import/export de fichiers, sans synchronisation automatique. Les documents du coffre ne figurent pas dans le résumé partagé.</div>`)}
function dataView(){return box('Sauvegardes et restauration',`<div class="notice">Données stockées sur cet appareil. Une suppression des données du navigateur peut les effacer. Exportez régulièrement une sauvegarde JSON.</div><div class="row">${btn('Exporter JSON complet','export:json','primary')}<label class="btn">Restaurer JSON<input id="restoreInput" type="file" accept=".json,application/json" hidden></label>${btn('Exporter CSV dépenses','export:expenses')}<label class="btn">Fusionner une sauvegarde JSON<input id="mergeInput" type="file" accept=".json,application/json" hidden></label><label class="btn">Importer un calendrier ICS<input id="icsInput" type="file" accept=".ics,text/calendar" hidden></label></div><p class="small">Schéma version ${VERSION} · ${db.trips.length} voyage(s). Restauration avec vérification et confirmation. Fusion JSON disponible avec aperçu des conflits et choix explicite de priorité.</p><h3>Apparence</h3>${btn('Basculer clair / sombre','theme:toggle')}<h3>Supprimer les données locales</h3>${btn('Tout effacer','clear:all','danger')}`)}
const forms={trips:{title:'Voyage',fields:x=>field('name','Nom','text',x.name,'required')+field('destination','Destination','text',x.destination)+field('start','Départ','date',x.start)+field('end','Retour','date',x.end)+select('mode','Participants',['solo','groupe'],x.mode||'solo')+select('status','Statut',['préparation','en cours','terminé','archivé'],x.status||'préparation')+field('budget','Budget prévu (EUR)','number',x.budget||'','min="0" step="0.01"')+area('notes','Notes',x.notes)},days:{title:'Journée ou trajet',fields:x=>field('title','Titre','text',x.title,'required')+field('day','Date','date',x.day)+select('kind','Type',['journée','train','avion','bus','voiture','bateau','marche','autre'],x.kind||'journée')+field('from','Départ','text',x.from)+field('to','Arrivée','text',x.to)+area('notes','Activités / notes',x.notes)},bookings:{title:'Réservation',fields:x=>field('name','Nom','text',x.name,'required')+select('type','Type',['hébergement','avion','train','bus','voiture','activité','autre'],x.type||'hébergement')+field('start','Date','date',x.start)+field('time','Heure','time',x.time)+field('place','Lieu','text',x.place)+field('reference','Référence','text',x.reference)+field('cost','Montant','number',x.cost||'','step="0.01" min="0"')+select('currency','Devise',['EUR','USD','GBP','CHF','JPY'],x.currency||'EUR')+area('notes','Notes',x.notes)+`<div><label>Justificatif (max. 400 Ko)</label><input type="file" name="attachmentFile" accept="application/pdf,image/*,text/*"></div>`},expenses:{title:'Dépense',fields:x=>field('name','Libellé','text',x.name,'required')+field('day','Date','date',x.day||now())+field('amount','Montant','number',x.amount,'required min="0" step="0.01"')+select('currency','Devise',['EUR','USD','GBP','CHF','JPY'],x.currency||'EUR')+select('category','Catégorie',['transport','hébergement','repas','activités','équipement','autre'],x.category||'autre')+`<div><label>Réservation associée (facultatif)</label><select name="bookingId"><option value="">Aucune</option>${related('bookings').map(b=>`<option value="${esc(b.id)}" ${x.bookingId===b.id?'selected':''}>${esc(b.name)} — ${money(b.cost||0,b.currency||'EUR')}</option>`).join('')}</select></div>`},packing:{title:'Article',fields:x=>field('name','Article','text',x.name,'required')+field('qty','Quantité','number',x.qty||1,'min="1" step="1"')+field('grams','Poids unitaire (g)','number',x.grams||0,'min="0" step="any"')},journal:{title:'Souvenir',fields:x=>field('title','Titre','text',x.title,'required')+field('day','Date','date',x.day||now())+field('place','Lieu','text',x.place)+area('notes','Journal',x.notes)+`<div><label>Photo (max. 400 Ko)</label><input type="file" name="photoFile" accept="image/*"></div>`},vault:{title:'Document chiffré',fields:x=>field('name','Nom du document','text',x.name,'required')+field('day','Date','date',x.day||now())+`<div><label>Fichier (max. 400 Ko)</label><input type="file" name="secretFile" required></div>`}};
function editForm(kind,item){const x=item||{},f=forms[kind];$('#dialog').classList.toggle('longForm',['trips','bookings','vault'].includes(kind));$('#dialogContent').innerHTML=`<h2>${item?.id?'Modifier':'Ajouter'} · ${f.title}</h2><form id="entityForm" data-kind="${kind}" data-id="${x.id||''}"><div class="fields">${f.fields(x)}</div><p><button type="submit" class="primary">Enregistrer</button></p></form>`;$('#dialog').showModal()}
async function fileData(file,max=400000){if(!file)return null;if(file.size>max)throw Error('Fichier trop volumineux (maximum 400 Ko).');return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function download(filename,content,type='application/octet-stream'){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function csv(rows){if(!rows.length)return '';const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))].filter(k=>!['photo','attachment','cipher','iv','salt','gpx'].includes(k));return '\ufeff'+[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n')}
function exportGPX(){const t=trip(),pts=t?.gpx||[];if(!pts.length)return toast('Aucune trace GPX');const segments=t.gpxSegments?.length?t.gpxSegments:[pts];download('voyager-trace.gpx',`<?xml version="1.0"?><gpx version="1.1" creator="VOYAGER" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>${esc(t.name)}</name>${segments.map(seg=>`<trkseg>${seg.map(p=>`<trkpt lat="${p[0]}" lon="${p[1]}"/>`).join('')}</trkseg>`).join('')}</trk></gpx>`,'application/gpx+xml')}
function shareHTML(){const t=trip();if(!t)return;const body=`<h1>${esc(t.name)}</h1><p>${esc(t.destination)} · ${date(t.start)} → ${date(t.end)}</p><h2>Itinéraire</h2><ol>${related('days').sort((a,b)=>(a.order||0)-(b.order||0)).map(d=>`<li>${esc(d.title)} — ${date(d.day)} : ${esc(d.notes)}</li>`).join('')}</ol><h2>Réservations</h2><ul>${related('bookings').map(b=>`<li>${esc(b.name)} — ${date(b.start)} (${esc(b.type)})</li>`).join('')}</ul><h2>Journal</h2>${related('journal').map(j=>`<h3>${esc(j.title)}</h3><p>${esc(j.notes)}</p>`).join('')}`;download('voyager-partage-lecture-seule.html',`<!doctype html><html lang="fr"><meta charset="utf-8"><title>${esc(t.name)}</title><style>body{font:17px system-ui;max-width:750px;margin:40px auto;padding:15px;line-height:1.6}</style>${body}</html>`,'text/html')}
async function derive(pass,salt){if(!crypto.subtle)throw Error('Le coffre nécessite HTTPS ou localhost (contexte sécurisé).');const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
function b64(buffer){const bytes=new Uint8Array(buffer),chunk=8190;let result='';for(let i=0;i<bytes.length;i+=chunk){const part=bytes.subarray(i,i+chunk);let binary='';for(let j=0;j<part.length;j++)binary+=String.fromCharCode(part[j]);result+=btoa(binary)}return result}
function un64(encoded){const clean=String(encoded||'');if(!clean)return new Uint8Array(0);const parts=[];let length=0;for(let i=0;i<clean.length;i+=10920){const decoded=atob(clean.slice(i,i+10920));const arr=new Uint8Array(decoded.length);for(let j=0;j<decoded.length;j++)arr[j]=decoded.charCodeAt(j);parts.push(arr);length+=arr.length}const out=new Uint8Array(length);let offset=0;for(const part of parts){out.set(part,offset);offset+=part.length}return out}


async function encrypt(content,pass){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(pass,salt),bytes=new TextEncoder().encode(content),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes);return {salt:b64(salt),iv:b64(iv),cipher:b64(cipher)}}
async function decrypt(v,pass){const key=await derive(pass,un64(v.salt));return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(v.iv)},key,un64(v.cipher)))}
function confirmDelete(kind,idValue){if(!confirm('Supprimer cet élément définitivement ?'))return;db[kind]=db[kind].filter(x=>x.id!==idValue);if(kind==='trips'){for(const k of ['days','bookings','expenses','packing','journal','vault'])db[k]=db[k].filter(x=>x.tripId!==idValue);tripId=db.trips[0]?.id||''}save();render()}
async function handleAction(code){const [verb,kind,val]=code.split(':');if(verb==='new'){if(kind!=='trips'&&!tripId)return toast('Créez d’abord un voyage');if(kind==='vault'&&!vaultUnlocked)return toast('Déverrouillez le coffre');editForm(kind);return}if(verb==='edit'){editForm(kind,db[kind].find(x=>x.id===val));return}if(verb==='del'){confirmDelete(kind,val);return}if(verb==='open'){tripId=kind;tab='dashboard';render();return}if(verb==='duplicate'){const t=db.trips.find(x=>x.id===kind);db.trips.push({...t,id:id(),name:t.name+' (copie)',status:'préparation'});save();render();return}if(verb==='move'){const ordered=related('days').sort((a,b)=>(a.order||0)-(b.order||0)),i=ordered.findIndex(x=>x.id===kind),j=i+Number(val);if(j<0||j>=ordered.length)return;[ordered[i],ordered[j]]=[ordered[j],ordered[i]];ordered.forEach((x,n)=>x.order=n+1);save();render();return}if(verb==='attachment'){const a=db.bookings.find(x=>x.id===kind)?.attachment;if(a){const link=document.createElement('a');link.href=a;link.download='confirmation';link.click()}return}if(verb==='unlock'){const pass=$('#vaultPass').value;if(pass.length<8)return alert('Utilisez une phrase secrète d’au moins 8 caractères.');if(related('vault').length){try{await decrypt(related('vault')[0],pass)}catch{return alert('Phrase secrète incorrecte ou document endommagé.')}}vaultUnlocked=pass;render();toast('Coffre déverrouillé');return}if(verb==='lock'){vaultUnlocked=null;render();return}if(verb==='openvault'){try{const v=db.vault.find(x=>x.id===kind),content=await decrypt(v,vaultUnlocked);const a=document.createElement('a');a.href=content;a.download=v.filename||v.name;a.click()}catch{alert('Déchiffrement impossible.')}return}if(verb==='theme'){db.settings.theme=db.settings.theme==='light'?'dark':'light';save();render();return}if(verb==='clear'){if(kind==='gpx'){if(confirm('Supprimer la trace GPX ?')){delete trip().gpx;save();render()}}else if(kind==='all'&&confirm('EFFACER toutes les données locales ? Une sauvegarde JSON est recommandée.')&&confirm('Dernière confirmation : suppression irréversible.')){db=blank();tripId='';save();render()}return}if(verb==='export'){if(kind==='json')download('voyager-sauvegarde-'+now()+'.json',JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2),'application/json');else if(kind==='gpx')exportGPX();else if(kind==='ics')exportICS();else if(kind==='html')shareHTML();else download('voyager-'+kind+'.csv',csv(related(kind)),'text/csv');return}if(verb==='print'){const html=sharePrint();const w=window.open('','_blank');if(!w)return alert('Autorisez les fenêtres contextuelles pour imprimer.');w.document.write(html);w.document.close();w.print()}}
function sharePrint(){return `<!doctype html><html lang="fr"><meta charset="utf-8"><title>Journal VOYAGER</title><style>body{font:16px system-ui;max-width:750px;margin:35px auto;line-height:1.6}article{page-break-inside:avoid;border-bottom:1px solid #ccc;padding:15px 0}img{max-width:450px}</style><h1>${esc(trip()?.name||'Voyage')} · Journal</h1>${related('journal').map(j=>`<article><h2>${esc(j.title)}</h2><p>${date(j.day)} · ${esc(j.place)}</p><p>${esc(j.notes)}</p>${j.photo?`<img src="${j.photo}">`:''}</article>`).join('')}</html>`}

// Synchronisation manuelle sans serveur : fusion par identifiant stable, aperçu et confirmation.
const COLLECTIONS=['trips','days','bookings','expenses','packing','journal','vault'];
function validBackup(o){return o&&o.schema===VERSION&&COLLECTIONS.every(k=>Array.isArray(o[k]))&&o.trips.every(t=>typeof t.id==='string')&&COLLECTIONS.every(k=>o[k].every(x=>typeof x.id==='string'))}
async function mergeBackup(file){
 try{
  const other=JSON.parse(await file.text());if(!validBackup(other))throw Error('Sauvegarde incompatible ou incomplète');
  const counts={added:0,conflicts:0,identical:0};
  for(const k of COLLECTIONS){const current=new Map(db[k].map(x=>[x.id,x]));for(const item of other[k]){if(!current.has(item.id))counts.added++;else if(JSON.stringify(current.get(item.id))===JSON.stringify(item))counts.identical++;else counts.conflicts++}}
  if(!confirm(`Fusionner ${counts.added} nouveaux éléments ?\n${counts.conflicts} conflits entre éléments de même identifiant.\n${counts.identical} identiques.\n\nSauvegardez d'abord votre appareil actuel. Annuler ne modifie rien.`))return;
  const preferIncoming=counts.conflicts?confirm(`Il existe ${counts.conflicts} conflits.\nOK : privilégier les données IMPORTÉES.\nAnnuler : conserver les données LOCALES.\nLes nouveaux éléments sont ajoutés dans les deux cas.`):false;
  const candidate=structuredClone(db);
  for(const k of COLLECTIONS){const map=new Map(candidate[k].map(x=>[x.id,x]));for(const item of other[k])if(!map.has(item.id)||preferIncoming)map.set(item.id,item);candidate[k]=[...map.values()]}
  // Préserver les réglages et taux locaux, sans exposer le coffre.
  const old=db;db=candidate;if(!save()){db=old;return}vaultUnlocked=null;tripId=db.trips.some(t=>t.id===tripId)?tripId:(db.trips[0]?.id||'');render();toast(`Fusion : ${counts.added} ajout(s), ${counts.conflicts} conflit(s)`);
 }catch(e){alert('Fusion impossible : '+e.message)}
}
function icsEscape(v){return String(v??'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function icsDate(d,t=''){return String(d||'').replace(/-/g,'')+(t?'T'+t.replace(':','')+'00':'')}
function exportICS(){
 if(!trip())return toast('Sélectionnez un voyage');
 const entries=[...related('days').filter(x=>x.day).map(x=>({uid:x.id,name:x.title,day:x.day,time:x.time||'',notes:x.notes})),...related('bookings').filter(x=>x.start).map(x=>({uid:x.id,name:x.name,day:x.start,time:x.time,notes:`${x.type||''} ${x.place||''} • Référence : ${x.reference||''}`}))];
 const out=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//VOYAGER//Travel OS//FR','CALSCALE:GREGORIAN'];
 for(const e of entries){out.push('BEGIN:VEVENT',`UID:${icsEscape(e.uid)}@voyager.local`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`${e.time?'DTSTART':'DTSTART;VALUE=DATE'}:${icsDate(e.day,e.time)}`,`SUMMARY:${icsEscape(e.name)}`,`DESCRIPTION:${icsEscape(e.notes)}`,'END:VEVENT')}
 out.push('END:VCALENDAR');download('voyager-'+(trip().name||'voyage').replace(/[^a-z0-9_-]/gi,'-')+'.ics',out.join('\r\n'),'text/calendar');
}
function unfoldICS(s){return s.replace(/\r?\n[ \t]/g,'').split(/\r?\n/)}
function icsUnescape(s){return String(s||'').replace(/\\[nN]/g,'\n').replace(/\\([,;\\])/g,'$1')}
async function importICS(file){
 try{if(!trip())throw Error('Sélectionnez un voyage');const txt=await file.text();if(!txt.includes('BEGIN:VCALENDAR'))throw Error('Calendrier ICS invalide');
 const lines=unfoldICS(txt),items=[];let item=null;
 for(const line of lines){if(line==='BEGIN:VEVENT'){item={};continue}if(line==='END:VEVENT'){if(item?.name&&item?.day)items.push(item);item=null;continue}if(!item)continue;const ix=line.indexOf(':');if(ix<0)continue;const key=line.slice(0,ix).split(';')[0].toUpperCase(),v=line.slice(ix+1);if(key==='SUMMARY')item.name=icsUnescape(v);if(key==='DESCRIPTION')item.notes=icsUnescape(v);if(key==='UID')item.uid=v;if(key==='DTSTART'&&/^\d{8}/.test(v)){item.day=v.slice(0,4)+'-'+v.slice(4,6)+'-'+v.slice(6,8);if(v.length>=15)item.time=v.slice(9,11)+':'+v.slice(11,13)}}
 if(!items.length)throw Error('Aucun événement avec date et titre');
 const known=new Set(db.days.filter(d=>d.tripId===tripId).map(d=>d.sourceUid).filter(Boolean));const fresh=items.filter(x=>{const k=x.uid||`${x.day}:${x.name}`;if(known.has(k))return false;known.add(k);return true});
 if(!confirm(`${items.length} événement(s) trouvés ; ${fresh.length} nouveaux. Importer comme journées/activités dans le voyage actif ?`))return;
 for(const x of fresh)db.days.push({id:id(),tripId,sourceUid:x.uid||`${x.day}:${x.name}`,title:x.name,day:x.day,kind:'journée',time:x.time||'',notes:(x.notes||'')+'\nImport ICS : vérifier le fuseau de l’heure source ; aucune conversion automatique.',order:related('days').length+1});save();render();toast(`${fresh.length} événement(s) importé(s)`)
 }catch(e){alert('Import ICS impossible : '+e.message)}
}

async function restore(file){try{const obj=JSON.parse(await file.text());if(obj.schema!==VERSION||!Array.isArray(obj.trips)||!['days','bookings','expenses','packing','journal','vault'].every(k=>Array.isArray(obj[k])))throw Error('Format de sauvegarde incompatible');if(!confirm(`Restaurer ${obj.trips.length} voyage(s) ? Cela REMPLACERA les données locales actuelles.`))return;const old=db;db=obj;if(!save()){db=old;return}tripId=db.trips[0]?.id||'';vaultUnlocked=null;render();toast('Restauration effectuée')}catch(e){alert('Restauration refusée : '+e.message)}}
function parseCSV(text){
 const raw=text.replace(/^\ufeff/,'');const first=raw.split(/\r?\n/)[0]||'';const sep=[';',',','\t'].sort((a,b)=>first.split(b).length-first.split(a).length)[0];
 const records=[];let cell='',record=[],quoted=false;
 for(let i=0;i<raw.length;i++){const c=raw[i];if(c==='"'){if(quoted&&raw[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){record.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&raw[i+1]==='\n')i++;record.push(cell);if(record.some(v=>v.trim()))records.push(record);record=[];cell=''}else cell+=c}
 record.push(cell);if(record.some(v=>v.trim()))records.push(record);if(records.length<2)return [];
 const norm=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');
 const headers=records.shift().map(norm);return records.map(cols=>Object.fromEntries(headers.map((h,i)=>[h,(cols[i]||'').trim()])));
}
function gearNumber(v){const n=String(v??'').trim().replace(/\s/g,'').replace(/[^\d,.-]/g,'');if(!n)return NaN;const comma=n.lastIndexOf(','),dot=n.lastIndexOf('.');let t=n;if(comma>=0&&dot>=0)t=comma>dot?n.replace(/\./g,'').replace(',','.'):n.replace(/,/g,'');else if(comma>=0)t=n.replace(',','.');return Number(t)}
function gearRow(r){
 const pick=(...keys)=>{for(const k of keys)if(r[k]!==undefined&&String(r[k]).trim()!=='')return r[k];return ''};
 const name=pick('name','nom','article','item','title','designation','equipement','materiel','produit','objet');if(!name)return null;
 const qty=Math.max(1,Math.round(gearNumber(pick('qty','quantite','quantity','nombre','count','qte'))||1));
 const candidates=[['grams',1],['poids_g',1],['weight_g',1],['poids_unitaire_g',1],['poids_unitaire_grammes',1],['unit_weight_g',1],['weight_grams',1],['masse_g',1],['poids_kg',1000],['weight_kg',1000],['poids_unitaire_kg',1000],['unit_weight_kg',1000],['weight_kilograms',1000]];
 let grams=NaN;for(const [key,factor] of candidates){if(r[key]!==undefined&&r[key]!==''){grams=gearNumber(r[key])*factor;break}}
 if(!Number.isFinite(grams)){
 const raw=pick('poids_unitaire','unit_weight','weight_per_unit','poids','weight','masse','poids_total','total_weight');
 if(raw){const unit=pick('unite_poids','weight_unit','unit','unite','poids_unite');const isKg=/\bkg\b|kilogram/i.test(raw+' '+unit);const isG=/\b(g|grammes?|grams?)\b/i.test(raw+' '+unit);if(isKg||isG)grams=gearNumber(raw)*(isKg?1000:1);else if(r.weight!==undefined && r.kind!==undefined && r.wearlimit!==undefined && r.qty!==undefined)grams=gearNumber(raw);else grams=NaN}
 }
 // Aucune conversion supposée lorsqu'une unité est ambiguë.
 return {name:String(name).trim(),qty,grams:Number.isFinite(grams)&&grams>=0?Math.round(grams*100)/100:null};
}
async function importGear(file){try{
 const rows=parseCSV(await file.text()).map(gearRow).filter(Boolean);if(!rows.length)return alert('Aucun article reconnu. Vérifiez les colonnes du CSV MY GEAR.');
 const key=n=>String(n||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
 const existing=new Map(related('packing').map(p=>[key(p.name),p]));const pending=new Map();
 for(const row of rows){const k=key(row.name);if(!k)continue;pending.set(k,row)}
 let additions=0,updates=0,unknown=0;for(const [k,row] of pending){if(existing.has(k))updates++;else additions++;if(row.grams===null)unknown++}
 const message=`Import MY GEAR : ${pending.size} article(s) unique(s).\n${additions} nouveau(x), ${updates} déjà présent(s).\n${unknown} poids non reconnu(s) (ils ne seront pas inventés).\n\nLes articles existants seront mis à jour SANS doublons, en conservant leurs cases de préparation. Les poids absents ne remplaceront pas les poids connus. Continuer ?`;
 if(!confirm(message))return;
 const previous=JSON.stringify(db.packing);
 for(const [k,row] of pending){const old=existing.get(k);if(old){old.qty=row.qty;if(row.grams!==null)old.grams=row.grams;old.source='MY GEAR';old.weightUnknown=row.grams===null&&!Number(old.grams)}else db.packing.push({id:id(),tripId,name:row.name,qty:row.qty,grams:row.grams??0,ready:false,source:'MY GEAR',weightUnknown:row.grams===null})}
 if(!save()){db.packing=JSON.parse(previous);return}render();toast(`${additions} ajout(s), ${updates} mise(s) à jour. ${unknown} poids à vérifier.`)
 }catch(e){alert('Import CSV impossible : '+e.message)}}


