const labels={dashboard:'Accueil',trips:'Voyages',days:'Itinéraire',bookings:'Réservations',budget:'Budget',maps:'Cartes',packing:'Préparation',vault:'Documents',journal:'Journal',share:'Partage & secours',data:'Paramètres',more:'Plus'};
