titles.more=['Tous vos outils','Préparer, explorer, conserver.'];titles.dashboard=['Votre prochain horizon','Tout votre voyage, au même endroit.'];titles.packing=['Préparation','L’essentiel, sans rien oublier.'];
db.points||=[];db.settings.layout||=['next','preparation','shortcuts','budget','bookings','stats'];db.settings.sizes||={next:'wide'};db.rateMeta||={};
let subview='list',searchQuery='',tripFilter='tous',customizing=false,calendarMonth=now().slice(0,7),mapData=null;
let committed=JSON.stringify(db), storageFault=false;
// Keep mutations atomic with respect to persisted state, including quota errors.
save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));committed=JSON.stringify(db);storageFault=false;return true}catch{db=JSON.parse(committed);storageFault=true;alert('Enregistrement impossible : stockage saturé ou indisponible. Modification annulée. Exportez vos données avant de continuer.');return false}};
function themeDark(){return db.settings.theme==='dark'||(db.settings.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches)}
function render(){if(!db.trips.some(t=>t.id===tripId))tripId=db.trips[0]?.id||'';document.body.classList.toggle('onDashboard',tab==='dashboard');document.body.classList.toggle('light',!themeDark());document.querySelector('meta[name="theme-color"]').content=themeDark()?'#082335':'#fffefd';$('#pageTitle').textContent=titles[tab]?.[0]||labels[tab];$('#subtitle').textContent=titles[tab]?.[1]||'';$('#customButton').hidden=tab!=='dashboard';$('#customButton').textContent=customizing?'Terminer':'Personnaliser';
 const nav=(k)=>`<button data-tab="${k}" class="${tab===k?'active':''}" ${tab===k?'aria-current="page"':''}>${icon(k)}<span>${labels[k]}</span></button>`;
 $('#sideNav').innerHTML=Object.keys(labels).filter(k=>k!=='more').map(nav).join('');$('#tabs').innerHTML=['dashboard','trips','days','budget','more'].map(nav).join('');
 let html='';if(db.trips.length&&!['dashboard','trips','data','more'].includes(tab))html+=choose();
 if(!db.trips.length&&!['trips','data','more','dashboard'].includes(tab))html+=empty('Votre aventure commence ici','Créez un voyage pour préparer votre itinéraire, vos réservations et vos bagages.','Créer un voyage','new:trips');
 else html+=({dashboard, trips,days,bookings,budget,maps,packing,vault,journal,share,data:dataView,more:moreView})[tab]();$('#view').innerHTML=html;updateConnection();
}
function empty(title,text,button,act){return `<section class="card empty">${icon('plane')}<h2>${title}</h2><p>${text}</p>${button?btn(button,act,'primary'):''}</section>`}
function readyPercent(tid=tripId){const ps=db.packing.filter(x=>x.tripId===tid);return ps.length?Math.round(ps.filter(x=>x.ready).length/ps.length*100):0}
function choose(){return `<div class="row between card"><label for="tripSelect">${icon('trips')} Voyage actif</label><select id="tripSelect" style="flex:1;min-width:140px;max-width:400px">${db.trips.map(t=>`<option value="${esc(t.id)}" ${t.id===tripId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>`}
function dashboard(){const t=trip();if(!t)return `<section class="welcome panorama"><div><div class="eyebrow">TRAVEL & EXPEDITION STUDIO</div><h2>Le prochain départ se prépare ici.</h2><p>Des premières idées aux souvenirs du retour.</p></div></section>${empty('Bienvenue dans VOYAGER','Votre espace est vide. Ajoutez votre premier voyage ou restaurez une sauvegarde dans les paramètres.','Créer mon premier voyage','new:trips')}${box('Déjà un carnet de voyages ?',`${btn('Importer ma sauvegarde','goto:data')}`)}`;
 const s=budgetSummary(),pct=readyPercent(),upcoming=related('bookings').filter(b=>b.start>=now()).sort((a,b)=>(a.start||'').localeCompare(b.start||'')).slice(0,3);
 const modules={next:`<div class="tripBanner panorama"><span class="pill">${esc(t.status||'préparation')} · ${esc(t.mode||'solo')}</span><h2>${esc(t.name)}</h2><p>${esc(t.destination)}</p><p>${date(t.start)} — ${date(t.end)}</p>${btn('Explorer mon itinéraire →','goto:days')}</div>`,preparation:box(`${icon('packing')} Préparation`,`<div class="row between"><span class="muted small">Votre liste de départ</span><strong>${pct} %</strong></div><div class="progress"><div style="width:${pct}%"></div></div><div class="checklist">${related('packing').slice(0,4).map(p=>`<label class="${p.ready?'done':''}"><input type="checkbox" data-ready="${esc(p.id)}" ${p.ready?'checked':''}>${esc(p.name)}</label>`).join('')||'<p>Ajoutez vos premiers indispensables.</p>'}</div>${btn('Préparer mes bagages →','goto:packing')}`),shortcuts:box('Votre atelier de voyage',`<div class="quickGrid">${['bookings','days','packing','budget','maps','journal'].map(k=>`<button data-tab="${k}">${icon(k)}${labels[k]}</button>`).join('')}</div>`),budget:box(`${icon('budget')} Budget du voyage`,`<div class="row between"><span class="muted small">Engagé · EUR</span><span class="pill">${s.missing.length?'Conversion incomplète':'Conversions renseignées'}</span></div><div class="stat accent">${money(s.total)}</div><p>${s.cap===null?'Budget prévu non défini':money(s.cap)+' prévus · '+money(s.cap-s.total)+' disponibles'}</p><div class="progress"><div style="width:${s.cap?Math.min(100,s.total/s.cap*100):0}%"></div></div>${btn('Voir mon budget →','goto:budget')}`),bookings:box(`${icon('bookings')} Prochaines réservations`,upcoming.map(b=>`<div class="item"><h3>${esc(b.name)}</h3><p>${date(b.start)} · ${esc(b.type)}</p></div>`).join('')||'<p>Aucune réservation à venir enregistrée.</p>'),stats:box('Votre carnet en chiffres',`<div class="metrics">${[['Voyages',db.trips.filter(x=>x.status!=='modèle').length],['Étapes',db.days.length],['Souvenirs',db.journal.length],['Voyages terminés',db.trips.filter(x=>x.status==='terminé').length]].map(([l,v])=>`<div><span class="small muted">${l}</span><div class="stat">${v}</div></div>`).join('')}</div>`)};
 return `<section class="welcome panorama"><div><div class="eyebrow">VOTRE CARNET D’EXPLORATION</div><h2>Bonjour, prêt pour le départ ?</h2><p>${esc(t.destination||'Votre prochaine destination vous attend.')}</p></div></section>${customizing?layoutEditor():''}<div class="dashboard">${db.settings.layout.filter(k=>modules[k]).map(k=>`<div class="module ${db.settings.sizes[k]==='wide'?'wide':''}">${modules[k]}</div>`).join('')}</div>`;
}
function layoutEditor(){return box('Composez votre accueil',`<p>Déplacez les modules et choisissez leur largeur. Le voyage actif reste toujours présent.</p>${db.settings.layout.map((k,i)=>`<div class="layoutLine"><strong>${({next:'Voyage actif',preparation:'Préparation',shortcuts:'Raccourcis',budget:'Budget',bookings:'Réservations',stats:'Statistiques'})[k]}</strong>${btn('↑',`layout:${i}:-1`)}${btn('↓',`layout:${i}:1`)}<select data-size="${k}" aria-label="Largeur du module ${k}"><option value="normal" ${db.settings.sizes[k]!=='wide'?'selected':''}>Standard</option><option value="wide" ${db.settings.sizes[k]==='wide'?'selected':''}>Large</option></select></div>`).join('')}${btn('Restaurer la disposition','layout:reset')}`)}
function trips(){let ts=db.trips.filter(t=>(tripFilter==='tous'||t.status===tripFilter)&&`${t.name} ${t.destination} ${t.notes}`.toLowerCase().includes(searchQuery.toLowerCase()));return `<div class="row between"><span class="small muted">${ts.length} voyage(s)</span>${btn('+ Nouveau voyage','new:trips','primary')}</div><div class="searchRow"><input id="searchTrips" type="search" placeholder="Rechercher une destination…" aria-label="Rechercher un voyage" value="${esc(searchQuery)}"></div><div class="segmented" aria-label="Statut des voyages">${[['tous','Tous'],['préparation','À venir'],['en cours','En cours'],['terminé','Terminés']].map(([v,l])=>btn(l,`filter:${v}`,tripFilter===v?'active':'')).join('')}</div><details ${['archivé','modèle'].includes(tripFilter)?'open':''}><summary>Filtres avancés · archives et modèles</summary><label for="statusFilter">Statut</label><select id="statusFilter">${['tous','préparation','en cours','terminé','archivé','modèle'].map(x=>`<option ${x===tripFilter?'selected':''}>${x}</option>`).join('')}</select>${btn('Mémoriser ces critères','filter:save')}</details><div class="tripList">${ts.map(t=>`<article class="tripTile"><div class="tripTitle"><div class="thumb" aria-hidden="true"></div><div><span class="pill">${esc(t.status)}</span><h3>${esc(t.name)}</h3><p>${esc(t.destination)}<br>${date(t.start)} — ${date(t.end)}</p></div></div><div class="progress"><div style="width:${readyPercent(t.id)}%"></div></div><div class="row">${btn('Ouvrir',`open:${t.id}`,'primary')}${btn('Actions',`tripmenu:${t.id}`)}</div></article>`).join('')||empty('Pas encore de voyage dans cette vue','Changez les filtres ou créez votre prochain départ.','','')}</div>`}
function itineraryItems(){return related('days').sort((a,b)=>(a.order||0)-(b.order||0))}
function days(){const list=itineraryItems();return `<div class="segmented">${[['list','Liste'],['map','Carte'],['calendar','Planning']].map(([v,l])=>btn(l,`view:${v}`,subview===v?'active':'')).join('')}</div>${subview==='map'?maps():subview==='calendar'?calendarView():box('Votre itinéraire',`<div class="row">${btn('+ Étape / journée','new:days','primary')}${btn('Exporter calendrier','export:ics')}</div><div class="timeline">${list.map((d,i)=>`<article class="item"><span class="pill">ÉTAPE ${i+1} · ${date(d.day)}</span><h3>${esc(d.title)}</h3><p>${esc(d.kind)} ${d.from?'· '+esc(d.from):''}${d.to?' → '+esc(d.to):''}</p>${d.duration?`<p>Durée saisie : ${Number(d.duration)} min · ${esc(d.durationSource||'source non précisée')}</p>`:''}<p>${esc(d.notes)}</p><div class="row">${btn('↑',`move:${d.id}:-1`)}${btn('↓',`move:${d.id}:1`)}${action('days',d.id)}</div></article>`).join('')||'<p>Ajoutez vos étapes. Aucune durée de trajet n’est calculée sans source.</p>'}</div>`)} `}
function calendarView(){const [year,month]=calendarMonth.split('-').map(Number),first=new Date(year,month-1,1),offset=(first.getDay()+6)%7,count=new Date(year,month,0).getDate();return box('Planning du voyage',`<div class="row between">${btn('‹','month:-1')}<label for="calendarMonth">Mois<input id="calendarMonth" type="month" value="${calendarMonth}"></label>${btn('›','month:1')}</div><div class="calendar">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<div class="dayHead">${x}</div>`).join('')}${Array.from({length:offset},()=>'<div aria-hidden="true"></div>').join('')}${Array.from({length:count},(_,i)=>{const day=`${calendarMonth}-${String(i+1).padStart(2,'0')}`;return `<div><strong>${i+1}</strong>${related('days').filter(d=>d.day===day).map(d=>btn(esc(d.title),`edit:days:${d.id}`)).join('')}${related('bookings').filter(d=>d.start===day).map(d=>btn(esc(d.name),`edit:bookings:${d.id}`)).join('')}</div>`}).join('')}</div><p class="small">Heures saisies dans le fuseau local de l’étape. Aucune conversion automatique de fuseau.</p>`)}
function connectionAlerts(){const bs=related('bookings').filter(b=>b.start&&b.time).sort((a,b)=>(a.start+a.time).localeCompare(b.start+b.time));const alerts=[];for(let i=1;i<bs.length;i++){const a=bs[i-1],b=bs[i];if(!a.end||!a.endTime||!a.arrivalPlace||a.arrivalPlace.trim().toLowerCase()!==(b.place||'').trim().toLowerCase())continue;const gap=(new Date(b.start+'T'+b.time)-new Date(a.end+'T'+a.endTime))/60000;if(gap<Number(b.buffer||60))alerts.push(`${a.name} → ${b.name} : ${gap} min entre arrivée et départ, marge saisie ${b.buffer||60} min. Vérifier fuseau et correspondance.`)}return alerts}
function bookings(){const alerts=connectionAlerts();return `${alerts.length?box('Correspondances à vérifier',alerts.map(x=>`<div class="notice warn">${esc(x)}</div>`).join('')):''}${box('Réservations & confirmations',`<div class="row">${btn('+ Réservation','new:bookings','primary')}${btn('Importer un texte / email','bookingimport:open')}</div><p class="small">Pièces jointes PDF et images conservées. Import texte / EML avec validation humaine ; aucune connexion à votre messagerie.</p>${related('bookings').sort((a,b)=>(a.start||'').localeCompare(b.start||'')).map(b=>`<article class="item"><div class="row between"><div><span class="pill">${esc(b.type)} · ${esc(b.status||'à vérifier')}</span><h3>${esc(b.name)}</h3></div><strong>${money(b.cost,b.currency||'EUR')}</strong></div><p>${date(b.start)} ${esc(b.time||'')} ${b.end?'→ '+date(b.end)+' '+esc(b.endTime||''):''}<br>${esc(b.place)} ${b.arrivalPlace?'→ '+esc(b.arrivalPlace):''}</p><p>Référence : ${esc(b.reference||'Non renseignée')}</p>${b.notes?`<p>${esc(b.notes)}</p>`:''}<div class="row">${b.attachment?btn('Justificatif',`attachment:${b.id}`):''}${action('bookings',b.id)}</div></article>`).join('')||'<p>Vos confirmations apparaîtront ici.</p>'}<p class="small">Alertes calculées uniquement avec lieux identiques, dates et heures d’arrivée/départ saisis. Aucun rappel système lorsque l’application est fermée.</p>`)}`}
function cents(n){return Math.round((Number(n)+Number.EPSILON)*100)}
function eur(e){const c=e.currency||'EUR',rate=Number(db.rates[c]);if(c!=='EUR'&&(!db.rateMeta[c]?.date||!db.rateMeta[c]?.source||!Number.isFinite(rate)||rate<=0))return NaN;return cents(Number(e.amount)*(c==='EUR'?1:rate))/100}
function budgetSummary(tid=tripId){const es=db.expenses.filter(x=>x.tripId===tid),bs=db.bookings.filter(x=>x.tripId===tid&&x.status!=='annulée'),missing=new Set(),cats={};let spent=0,reserved=0;
 for(const e of es){const n=eur(e);if(!Number.isFinite(n)){missing.add(e.currency);continue}spent+=cents(n);cats[e.category||'autre']=(cats[e.category||'autre']||0)+cents(n)}
 for(const b of bs){const amount=Number(b.cost||0);if(!amount)continue;const linked=es.filter(e=>e.bookingId===b.id),same=linked.filter(e=>e.currency===(b.currency||'EUR')).reduce((s,e)=>s+Number(e.amount),0);const other=linked.filter(e=>e.currency!==(b.currency||'EUR')).reduce((s,e)=>{const v=eur(e);return s+(Number.isFinite(v)?v:0)},0);const n=eur({amount:Math.max(0,amount-same),currency:b.currency||'EUR'});if(!Number.isFinite(n)){missing.add(b.currency);continue}const v=Math.max(0,cents(n)-cents(other));reserved+=v;const cat=b.type==='hébergement'?'hébergement':b.type==='activité'?'activités':'transport';cats[cat]=(cats[cat]||0)+v}
 const t=db.trips.find(x=>x.id===tid);return {spent:spent/100,reserved:reserved/100,total:(spent+reserved)/100,cap:t?.budget!==''&&t?.budget!=null?Number(t.budget):null,cats:Object.fromEntries(Object.entries(cats).map(([k,v])=>[k,v/100])),missing:[...missing]}}
function budget(){const s=budgetSummary(),colors=['#16bdda','#9c79ed','#eea74d','#e774a2','#6cc7a6','#7f9dab'];let angle=0;const gradients=Object.entries(s.cats).filter(([,v])=>v>0).map(([,v],i)=>{const from=angle;angle+=s.total?v/s.total*360:0;return `${colors[i%colors.length]} ${from}deg ${angle}deg`});return `${s.missing.length?`<div class="notice warn">Total incomplet : taux daté et source requis pour ${s.missing.map(esc).join(', ')}. Les montants non convertibles sont exclus et restent visibles ci-dessous.</div>`:''}${box('Aperçu du budget',`<div class="budgetHero"><div class="donut" style="background:${gradients.length?'conic-gradient('+gradients.join(',')+')':'var(--line)'}"><div><strong>${money(s.total)}</strong>Engagé · EUR<br>${s.missing.length?'conversion incomplète':'réel + solde des réservations'}</div></div><div class="legend">${Object.entries(s.cats).map(([k,v],i)=>`<div><span><i style="background:${colors[i%colors.length]}"></i>${esc(k)}</span><strong>${money(v)}</strong></div>`).join('')||'<p>Votre répartition apparaîtra avec vos premières dépenses.</p>'}</div></div>`)}<div class="metrics">${[['Prévu',s.cap===null?'Non défini':money(s.cap)],['Dépensé',money(s.spent)],['À régler',money(s.reserved)],['Disponible',s.missing.length?'Incomplet':s.cap===null?'Non défini':money(s.cap-s.total)]].map(([l,v])=>`<div class="card"><span class="muted small">${l}</span><div class="stat">${v}</div></div>`).join('')}</div>${box('Votre enveloppe',`<form id="tripBudgetForm" class="fields">${field('budget','Budget prévu · EUR','number',trip()?.budget??'','min="0" step="0.01" required')}<div><label>&nbsp;</label><button class="primary">Enregistrer</button></div></form><p class="small">Une dépense liée règle partiellement ou totalement sa réservation ; seul le solde non payé reste engagé. Une réservation annulée est exclue ; ses dépenses restent réelles.</p>`)}${box('Dépenses',`${btn('+ Dépense','new:expenses','primary')}${related('expenses').map(e=>`<div class="item"><div class="row between"><h3>${esc(e.name)}</h3><strong>${money(e.amount,e.currency)}</strong></div><p>${date(e.day)} · ${esc(e.category)} · ${Number.isFinite(eur(e))?money(eur(e))+' en EUR':'Taux à renseigner'} ${e.bookingId?'· Réservation liée':''}</p>${action('expenses',e.id)}</div>`).join('')||'<p>Aucune dépense enregistrée.</p>'}`)}${box('Réservations incluses',related('bookings').map(b=>`<div class="item row between"><span>${esc(b.name)} <span class="pill">${esc(b.status||'à vérifier')}</span></span><strong>${money(b.cost,b.currency||'EUR')}</strong>${btn('Modifier',`edit:bookings:${b.id}`)}</div>`).join('')||'<p>Aucune réservation.</p>')}${ratesView()}${box('Comparaisons & scénarios',`<div class="statsBars">${db.trips.filter(t=>t.status!=='modèle').map(t=>{const x=budgetSummary(t.id);return `<div><span>${esc(t.name)}</span><div class="bar"><span style="width:${x.cap?Math.min(100,x.total/x.cap*100):0}%"></span></div><strong>${money(x.total)}${x.missing.length?' *':''}</strong></div>`}).join('')}</div><p class="small">Barres : engagé / prévu. * Conversion incomplète.</p><form id="scenarioForm" class="fields">${field('extra','Hypothèse de coût supplémentaire · EUR','number',db.settings.scenarioExtra||0,'step="0.01"')}${field('margin','Marge sur l’engagé · %','number',db.settings.scenarioMargin||0,'min="0" step="any"')}<div><button>Calculer le scénario</button></div></form><div id="scenarioResult" class="notice">${scenarioText()}</div><p class="small">Calcul exploratoire, sans modification du budget ni ajout de dépense.</p>`)}`}
function scenarioText(){const s=budgetSummary(),v=cents(s.total*(1+Number(db.settings.scenarioMargin||0)/100)+Number(db.settings.scenarioExtra||0))/100;return `Hypothèse totale : ${money(v)}${s.cap!==null?' · disponible : '+money(s.cap-v):''}${s.missing.length?' · base incomplète, taux manquants':''}`}
function ratesView(){return `<details><summary>Taux manuels · date et source obligatoires</summary><p class="small">Valeur en EUR pour 1 unité. Aucun taux en direct. Les taux hérités restent non vérifiés jusqu’à votre confirmation. Les totaux sont recalculés au taux courant enregistré.</p><form id="ratesForm"><div class="fields">${['USD','GBP','CHF','JPY',...Object.keys(db.rates).filter(k=>!['EUR','USD','GBP','CHF','JPY'].includes(k))].map(c=>`<div><h3>${esc(c)} → EUR</h3>${field(c,c+' · taux','number',db.rates[c]??'','min="0.000000001" step="any"')}${field(c+'_date','Date du taux','date',db.rateMeta[c]?.date||'')}${field(c+'_source','Source','text',db.rateMeta[c]?.source||'')}</div>`).join('')}</div><button class="primary">Enregistrer les taux renseignés</button></form><form id="currencyForm" class="fields">${field('code','Autre devise ISO (3 lettres)','text','','pattern="[A-Za-z]{3}" maxlength="3" required')}<div><label>&nbsp;</label><button>Ajouter la devise</button></div></form></details>`}
function packing(){const ps=related('packing');return box('Votre liste de départ',`<div class="row between"><strong>${ps.filter(x=>x.ready).length}/${ps.length} articles prêts</strong><span class="pill">${readyPercent()} %</span></div><div class="progress"><div style="width:${readyPercent()}%"></div></div><div class="row">${btn('+ Article','new:packing','primary')}<label class="btn">Importer MY GEAR CSV<input id="gearInput" type="file" accept=".csv,text/csv" hidden></label>${btn('Exporter CSV','export:packing')}</div><div class="checklist">${ps.map(p=>`<div class="item packingItem"><div class="row between"><label class="${p.ready?'done':''}"><input type="checkbox" data-ready="${esc(p.id)}" ${p.ready?'checked':''}>${esc(p.name)} · ×${Number(p.qty)||1}</label>${btn('⋯',`packingmenu:${p.id}`)}</div><p>${p.weightUnknown?'Poids inconnu':(Number(p.grams)||0)+' g / unité'} · ${esc(p.kind||'base')}${p.source?' · '+esc(p.source):''}</p></div>`).join('')||'<p>Ajoutez vos indispensables ou importez votre inventaire MY GEAR.</p>'}</div><div class="notice">Poids total connu : <strong>${(ps.reduce((a,p)=>a+(p.weightUnknown?0:Number(p.grams)||0)*(Number(p.qty)||1),0)/1000).toLocaleString('fr-FR')} kg</strong> · ${ps.filter(x=>x.weightUnknown).length} poids à vérifier.<br>Les quantités sont appliquées au poids unitaire. Le CSV réimporté met à jour les articles reconnus sans perdre les cases cochées.</div><details><summary>Répartition du poids connu</summary>${['base','porté','consommable'].map(k=>`<p>${k} : ${(ps.filter(p=>(p.kind||'base')===k&&!p.weightUnknown).reduce((a,p)=>a+(Number(p.grams)||0)*(Number(p.qty)||1),0)/1000).toLocaleString('fr-FR')} kg</p>`).join('')}</details>`)}
function maps(){return `<div class="mapLayout"><aside class="mapStages card"><h2>Étapes du voyage</h2>${itineraryItems().map((d,i)=>`<div class="item"><span class="pill">${i+1} · ${date(d.day)}</span><h3>${esc(d.title)}</h3>${btn('Détails',`edit:days:${d.id}`)}</div>`).join('')||'<p>Aucune étape.</p>'}</aside><div>${box('Cartes & itinéraire',`<p>Votre GPX reste disponible hors ligne une fois importé. Aucun fond topographique n’est téléchargé automatiquement.</p><label for="gpxInput">Importer GPX (20 000 points maximum)</label><input id="gpxInput" type="file" accept=".gpx,application/gpx+xml,text/xml"><div class="row">${btn('Exporter GPX','export:gpx')}${btn('Supprimer GPX','clear:gpx','danger')}</div><div class="map">${svgMap(trip()?.gpx)}</div><label for="mapInput">Carte image hors ligne dont vous possédez les droits · max. 400 Ko</label><input id="mapInput" type="file" accept="image/png,image/jpeg,image/webp">${trip()?.mapImage?`<img class="mapBack" src="${safeImage(trip().mapImage)}" alt="Carte image importée par l’utilisateur">${btn('Retirer cette image','map:clear')}`:''}<div class="notice">Image non géoréférencée : le GPX n’est pas superposé. Aucun guidage GPS, téléchargement de tuiles ou fond topographique fourni. Vérifiez droits et lisibilité de votre image. N’utilisez pas cette vue comme seul moyen de navigation.</div>`)}${box('Points d’intérêt',`${btn('+ Point d’intérêt','poi:new','primary')}${(db.points||[]).filter(p=>p.tripId===tripId).map(p=>`<div class="item"><h3>${esc(p.name)}</h3><p>${Number(p.lat)}, ${Number(p.lon)} · ${esc(p.type)}<br>${esc(p.notes)}</p><div class="row">${btn('Ouvrir sur OpenStreetMap',`poi:open:${p.id}`)}${btn('Modifier',`poi:edit:${p.id}`)}${btn('Supprimer',`poi:del:${p.id}`,'danger')}</div></div>`).join('')||'<p>Aucun point enregistré. Les coordonnées saisies restent accessibles hors ligne.</p>'}<p class="small">OpenStreetMap s’ouvre dans un nouvel onglet avec connexion réseau ; les tuiles ne sont pas mises en cache par VOYAGER.</p>`)}</div></div>`}
function safeImage(v){return /^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=\s]+$/.test(v||'')?v:''}
function journal(){return box('Votre carnet de voyage',`<div class="row">${btn('+ Souvenir','new:journal','primary')}${btn('Imprimer / enregistrer en PDF','print:journal')}</div><p class="small">L’export PDF utilise l’impression du navigateur, puis « Enregistrer au format PDF ».</p>${related('journal').sort((a,b)=>(b.day||'').localeCompare(a.day||'')).map(j=>`<article class="item"><span class="pill">${date(j.day)} · ${esc(j.place)}</span><h3>${esc(j.title)}</h3><p style="white-space:pre-wrap">${esc(j.notes)}</p>${j.photo?`<img class="journalPhoto" src="${safeImage(j.photo)}" alt="Photo de ${esc(j.title)}">`:''}${action('journal',j.id)}</article>`).join('')||'<p>Conservez vos étapes, vos photos et vos impressions au fil du voyage.</p>'}<details><summary>Bilan de voyage</summary><form id="reviewForm">${area('review','Ce que je retiens / ce que je changerais',trip()?.review||'')}<button class="primary">Enregistrer le bilan</button></form></details>`)}
function vault(){return box('Votre coffre documentaire',`<div class="notice">Contenu des fichiers chiffré AES-256-GCM, clé dérivée PBKDF2-SHA256 · 180 000 itérations. Noms, dates et noms de fichiers restent visibles dans la sauvegarde. Aucun mot de passe enregistré. Phrase perdue = fichiers irrécupérables.</div>${!vaultUnlocked?`<label for="vaultPass">Phrase secrète · minimum 8 caractères</label><input id="vaultPass" type="password" autocomplete="off">${btn('Déverrouiller le coffre','unlock:vault','primary')}`:`<div class="row">${btn('+ Document','new:vault','primary')}${btn('Verrouiller','lock:vault')}</div><p class="small">Verrouillage lors du changement de voyage, de la mise en arrière-plan et après 5 minutes d’inactivité.</p>${related('vault').map(v=>`<div class="item"><h3>${esc(v.name)}</h3><p>${date(v.day)} · contenu chiffré</p><div class="row">${btn('Déchiffrer & télécharger',`openvault:${v.id}`)}${btn('Supprimer',`del:vault:${v.id}`,'danger')}</div></div>`).join('')||'<p>Aucun document. La première pièce établit la phrase de ce voyage.</p>'}`}<p class="small">Après fusion de coffres avec des phrases différentes, verrouillez puis saisissez la phrase du document souhaité. Un fichier endommagé ne bloque pas les autres.<br>400 Ko maximum par fichier, avant chiffrement. Justificatifs de réservation et photos du journal ne sont pas chiffrés : utilisez ce coffre pour les documents sensibles. Export JSON complet nécessaire pour sauvegarder le coffre.</p>`)}
function share(){return `${box('Itinéraire partageable',`<p>Un fichier HTML autonome, en lecture seule. Vérifiez les sections avant l’export ; aucun envoi automatique.</p>${btn('Préparer le partage','share:preview','primary')}<div class="row">${btn('Itinéraire CSV','export:days')}${btn('Bagages CSV · MY GEAR','export:packing')}${btn('Dépenses CSV','export:expenses')}${btn('Trace GPX','export:gpx')}${btn('Calendrier ICS','export:ics')}</div><div class="notice">Échanges manuels par fichiers. Aucune synchronisation MY GEAR, TRAIL COMMAND ou NEXUS active.</div>`)}${box('Fiche d’urgence privée',`<form id="emergencyForm" class="fields">${field('contact','Contact de confiance','text',trip()?.emergency?.contact||'')}${field('phone','Téléphone avec indicatif','tel',trip()?.emergency?.phone||'')}${area('protocol','Protocole convenu / rendez-vous / informations utiles',trip()?.emergency?.protocol||'')}<div><button class="primary">Enregistrer</button></div></form><p class="small">Informations stockées en clair sur cet appareil. Ne renseignez que le nécessaire ; pour les pièces sensibles, utilisez le coffre.</p>${btn('Prévisualiser la fiche à exporter','emergency:preview')}`)}`}
function moreView(){return `<div class="moreGrid">${['bookings','maps','packing','vault','journal','share','data'].map(k=>`<button data-tab="${k}">${icon(k)}${labels[k]}</button>`).join('')}</div>${box('Votre espace reste indépendant','<p>Les données résident sur cet appareil. Sauvegardez avant tout changement de navigateur ou de téléphone.</p>')}`}
function dataView(){return `${box('Sauvegardes & restauration',`<div class="notice">Stockage local sur cet appareil. Exportez régulièrement votre JSON complet : les fichiers chiffrés y sont inclus. Les sauvegardes locales restent sur le même appareil.</div><div class="row">${btn('Exporter JSON complet','export:json','primary')}<label class="btn">Restaurer JSON<input id="restoreInput" type="file" accept=".json" hidden></label><label class="btn">Fusionner JSON<input id="mergeInput" type="file" accept=".json" hidden></label><label class="btn">Importer calendrier ICS<input id="icsInput" type="file" accept=".ics" hidden></label></div><p class="small">Schéma 1 compatible avec les six archives historiques · Studio ${RELEASE}. Aperçu et historique automatique avant remplacement ou fusion.</p>${btn('Afficher l’historique local','history:list')}${btn('Demander un stockage persistant','storage:persist')}<div id="historyList"></div>`)}${box('Apparence',`<label for="themeSelect">Thème</label><select id="themeSelect">${[['system','Automatique · système'],['light','Clair · océan & sable'],['dark','Sombre · graphite & turquoise']].map(([v,l])=>`<option value="${v}" ${db.settings.theme===v?'selected':''}>${l}</option>`).join('')}</select>`)}${box('Hors ligne & mises à jour',`<p id="offlineDetail">${navigator.serviceWorker?.controller?'Application contrôlée par le service worker.':'Première ouverture : installation du cache en cours ou service worker indisponible.'} Le GPX, les données et pièces jointes locales n’exigent aucun réseau.</p><div class="row">${btn('Vérifier les mises à jour','sw:check')}${btn('Activer la mise à jour disponible','sw:activate')}</div><p class="small">Les cartes externes ne sont pas disponibles hors ligne. Aucune notification système ni synchronisation cloud. La mise à jour des fichiers ne supprime pas les données.</p>`)}${box('Confidentialité & contrôle',`<p>Aucune télémétrie ni requête externe automatique. Seul le lien explicite OpenStreetMap quitte l’application. Hébergement HTTPS nécessaire pour l’installation PWA et le chiffrement.</p><div class="row">${btn('Tout effacer sur cette version de test','clear:all','danger')}</div><p class="small">Clé isolée : voyager_studio_test_v2. Les données voyager_v1 ne sont jamais lues ou modifiées automatiquement. Une purge de navigateur supprime aussi l’historique de sauvegarde.</p>`)}`}
const originalFields=Object.fromEntries(Object.entries(forms).map(([k,v])=>[k,v.fields]));
forms.trips.fields=x=>originalFields.trips(x).replace('value="archivé"','value="archivé"')+`<div><label><input type="checkbox" name="isTemplate" ${x.status==='modèle'?'checked':''}> Enregistrer comme modèle de voyage</label></div>`;
forms.days.fields=x=>originalFields.days(x)+field('time','Heure locale (facultatif)','time',x.time||'')+field('duration','Durée saisie (minutes, facultatif)','number',x.duration||'','min="0"')+field('durationSource','Source de la durée','text',x.durationSource||'');
forms.bookings.fields=x=>originalFields.bookings(x)+field('end','Date d’arrivée / fin','date',x.end||'')+field('endTime','Heure d’arrivée / fin','time',x.endTime||'')+field('arrivalPlace','Lieu d’arrivée / fin','text',x.arrivalPlace||'')+field('buffer','Marge correspondance saisie (min)','number',x.buffer||60,'min="0"')+select('status','Confirmation',['à vérifier','confirmée','annulée'],x.status||'à vérifier');
forms.packing.fields=x=>originalFields.packing(x)+select('kind','Type de poids',['base','porté','consommable'],x.kind||'base');
// Include custom ISO currencies in reservation/expense forms.
for(const k of ['bookings','expenses']){const f=forms[k].fields;forms[k].fields=x=>f(x).replace(/(<select[^>]*name="currency"[^>]*>)([\s\S]*?)(<\/select>)/,(_,a,b,c)=>a+b+Object.keys(db.rates).filter(v=>!['EUR','USD','GBP','CHF','JPY'].includes(v)).map(v=>`<option value="${esc(v)}" ${x.currency===v?'selected':''}>${esc(v)}</option>`).join('')+c)}
function backupIssue(o){if(!o||o.schema!==1)return 'Version de schéma non prise en charge';if(!COLLECTIONS.every(k=>Array.isArray(o[k])))return 'Collections historiques manquantes';const tids=new Set();for(const k of [...COLLECTIONS,...(o.points?['points']:[])]){if(!Array.isArray(o[k]))return 'Collection invalide';const ids=new Set();for(const x of o[k]){if(!x||typeof x!=='object'||typeof x.id!=='string'||!/[a-zA-Z0-9]/.test(x.id)||!/^[a-zA-Z0-9._-]+$/.test(x.id)||ids.has(x.id))return `Identifiant invalide ou doublon dans ${k}`;ids.add(x.id);if(k==='trips')tids.add(x.id);if(k!=='trips'&&!tids.has(x.tripId))return `Voyage parent absent dans ${k}`;if(k==='trips'&&typeof x.name!=='string')return 'Nom du voyage invalide';if((k==='expenses'||k==='bookings')&&x.currency&&!/^[A-Z]{3}$/.test(x.currency))return 'Devise invalide';if(k==='expenses'&&(!Number.isFinite(Number(x.amount))||Number(x.amount)<0))return 'Montant invalide';if(k==='bookings'&&x.cost!==undefined&&(!Number.isFinite(Number(x.cost))||Number(x.cost)<0))return 'Coût réservation invalide';if(k==='packing'&&(!Number.isFinite(Number(x.qty))||Number(x.qty)<1||!Number.isFinite(Number(x.grams))||Number(x.grams)<0))return 'Quantité ou poids invalide';if(k==='vault'&&!['salt','iv','cipher'].every(v=>typeof x[v]==='string'&&/^[A-Za-z0-9+/]*={0,2}$/.test(x[v])))return 'Contenu chiffré invalide';if(k==='journal'&&x.photo&&!safeImage(x.photo))return 'Photo invalide';if(k==='bookings'&&x.attachment&&!/^data:(application\/pdf|image\/(png|jpeg|webp)|text\/plain);base64,[A-Za-z0-9+/=\s]+$/.test(x.attachment))return 'Type de pièce jointe non autorisé';if(k==='trips'&&x.mapImage&&!safeImage(x.mapImage))return 'Carte image invalide';if(k==='trips'&&x.gpxSegments&&(!Array.isArray(x.gpxSegments)||!x.gpxSegments.every(seg=>Array.isArray(seg)&&seg.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&Math.abs(p[0])<=90&&Math.abs(p[1])<=180))||JSON.stringify(x.gpxSegments.flat())!==JSON.stringify(x.gpx)))return 'Segments GPX invalides';if(k==='trips'&&x.gpx&&(!Array.isArray(x.gpx)||x.gpx.length>20000||!x.gpx.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&Math.abs(p[0])<=90&&Math.abs(p[1])<=180)))return 'Trace GPX invalide'}}
 for(const e of o.expenses){if(e.bookingId&&!o.bookings.some(b=>b.id===e.bookingId&&b.tripId===e.tripId))return 'Réservation liée absente ou autre voyage'}
 if(o.rates&&Object.entries(o.rates).some(([c,r])=>!(/^[A-Z]{3}$/.test(c))||!Number.isFinite(Number(r))||Number(r)<=0))return 'Taux de change invalide';return ''}
function validBackup(o){return !backupIssue(o)}
function normalizeBackup(o){const v=structuredClone(o);v.points||=[];v.rates||={EUR:1};v.rates.EUR=1;v.settings||={};v.settings.theme||='system';v.settings.layout=Array.isArray(v.settings.layout)&&new Set(v.settings.layout).size===6&&v.settings.layout.every(k=>['next','preparation','shortcuts','budget','bookings','stats'].includes(k))?v.settings.layout:['next','preparation','shortcuts','budget','bookings','stats'];v.settings.sizes||={next:'wide'};v.rateMeta||={};return v}
function historyDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('voyager_studio_history',1);r.onupgradeneeded=()=>r.result.createObjectStore('backups',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function historyWrite(label){const d=await historyDB(),entry={id:id(),at:new Date().toISOString(),label,data:JSON.parse(committed)};await new Promise((resolve,reject)=>{const t=d.transaction('backups','readwrite');t.objectStore('backups').put(entry);t.oncomplete=resolve;t.onerror=()=>reject(t.error)});d.close();return entry.id}
async function historyRead(){const d=await historyDB();return new Promise((resolve,reject)=>{const t=d.transaction('backups'),r=t.objectStore('backups').getAll();r.onsuccess=()=>{resolve(r.result);d.close()};r.onerror=()=>reject(r.error)})}
async function restore(file){try{const obj=JSON.parse(await file.text()),issue=backupIssue(obj);if(issue)throw Error(issue);if(!confirm(`APERÇU : ${obj.trips.length} voyage(s), ${obj.bookings.length} réservation(s), ${obj.vault.length} document(s) chiffré(s).\nRemplacer les données de CETTE VERSION DE TEST ? Une sauvegarde locale sera enregistrée d’abord.`))return;await historyWrite('Avant restauration');db=normalizeBackup(obj);if(!save())return;tripId=db.trips[0]?.id||'';vaultUnlocked=null;render();toast('Restauration effectuée et version précédente conservée.')}catch(e){alert('Restauration refusée : '+e.message)}}
async function mergeBackup(file){try{const other=JSON.parse(await file.text());const issue=backupIssue(other);if(issue)throw Error(issue);let added=0,conflicts=0;for(const k of [...COLLECTIONS,'points'])for(const x of other[k]||[]){const old=(db[k]||[]).find(y=>y.id===x.id);if(!old)added++;else if(JSON.stringify(old)!==JSON.stringify(x))conflicts++}if(!confirm(`Fusion : ${added} nouveaux éléments, ${conflicts} conflits. Continuer ? Sauvegarde automatique préalable.`))return;const incoming=conflicts&&confirm('Conflits : OK privilégie les éléments importés ; Annuler conserve les éléments locaux. Les nouveaux éléments seront ajoutés.');const candidate=structuredClone(db);for(const k of [...COLLECTIONS,'points']){const m=new Map((candidate[k]||[]).map(x=>[x.id,x]));for(const x of other[k]||[])if(!m.has(x.id)||incoming)m.set(x.id,x);candidate[k]=[...m.values()]}const issue2=backupIssue(candidate);if(issue2)throw Error(issue2);await historyWrite('Avant fusion');db=normalizeBackup(candidate);if(!save())return;vaultUnlocked=null;render();toast('Fusion effectuée.')}catch(e){alert('Fusion impossible : '+e.message)}}
// CSV parser retained from historical corrected archives. Explicit malformed quote check.
const historicalCSV=parseCSV;
parseCSV=function(text){let quote=false;for(let i=0;i<text.length;i++)if(text[i]==='"'){if(quote&&text[i+1]==='"')i++;else quote=!quote}if(quote)throw Error('Guillemets CSV non fermés');return historicalCSV(text)};
const historicalGearRow=gearRow;
gearRow=function(r){const x=historicalGearRow(r);if(!x)return null;x.kind=/consomm|consum/.test(r.kind||r.type||'')?'consommable':/port|worn/.test(r.kind||r.type||'')?'porté':'base';
 const totalKey=['poids_total','total_weight'].find(k=>r[k]);if(totalKey&&!['grams','poids_g','weight_g','poids_unitaire','unit_weight','poids','weight','poids_kg'].some(k=>r[k])){if(x.grams!==null)x.grams=Math.round(x.grams/x.qty*100)/100}return x};
async function importGear(file){try{if(!trip())throw Error('Sélectionnez un voyage');const buf=await file.arrayBuffer();let txt;try{txt=new TextDecoder('utf-8',{fatal:true}).decode(buf)}catch{txt=new TextDecoder('windows-1252').decode(buf)}const rows=parseCSV(txt).map(gearRow).filter(Boolean);if(!rows.length)throw Error('Aucun article reconnu');const key=n=>n.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');const pending=new Map(rows.map(x=>[key(x.name),x]));const existing=new Map(related('packing').map(x=>[key(x.name),x]));let updates=0;for(const k of pending.keys())if(existing.has(k))updates++;const unknown=[...pending.values()].filter(x=>x.grams===null).length;
 const preview=[...pending.values()].slice(0,8).map(x=>`${x.name} ×${x.qty} · ${x.grams===null?'poids inconnu':x.grams+' g/unité'}`).join('\n');if(!confirm(`${pending.size} articles uniques : ${pending.size-updates} nouveaux, ${updates} mis à jour. ${rows.length-pending.size} doublon(s), dernière ligne prioritaire. ${unknown} poids inconnus.\n${preview}\n${pending.size>8?'…\n':''}Importer ? Cases cochées et poids déjà connus conservés.`))return;await historyWrite('Avant CSV MY GEAR');for(const [k,x]of pending){const old=existing.get(k);if(old){old.qty=x.qty;old.kind=x.kind;if(x.grams!==null){old.grams=x.grams;old.weightUnknown=false}else old.weightUnknown=old.weightUnknown||(!Number.isFinite(Number(old.grams)));old.source='MY GEAR'}else db.packing.push({...x,id:id(),tripId,grams:x.grams??0,weightUnknown:x.grams===null,ready:false,source:'MY GEAR'})}if(save()){render();toast('CSV MY GEAR importé.')}}catch(e){alert('Import CSV impossible : '+e.message)}}
function csv(rows){if(!rows.length)return '';const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))].filter(k=>!['photo','attachment','cipher','iv','salt','gpx'].includes(k));const safe=v=>{const s=String(v);return /^[=+@\-\t\r]/.test(s)?"'"+s:s};return '\ufeff'+[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(row=>row.map(v=>'"'+safe(v).replace(/"/g,'""')+'"').join(';')).join('\r\n')}
function bookingImport(){ $('#dialogContent').innerHTML=`<h2>Importer une confirmation</h2><p>Collez le texte d’un email ou chargez un .txt / .eml non encodé. Les suggestions doivent être relues avant enregistrement.</p><label for="bookingTextFile">Texte / email</label><input id="bookingTextFile" type="file" accept=".txt,.eml,text/plain,message/rfc822"><label for="bookingText">Texte original</label><textarea id="bookingText" style="min-height:220px"></textarea>${btn('Préparer une fiche à vérifier','bookingimport:extract','primary')}<p class="small">Les PDF sont acceptés en justificatifs dans la fiche réservation ; pas d’OCR ni extraction PDF. Les emails MIME encodés doivent être copiés en texte clair.</p>`;$('#dialog').showModal()}
function extractBooking(text){const line=text.split(/\r?\n/).find(l=>/^(subject|objet):/i.test(l));const dates=text.match(/\b20\d{2}-\d{2}-\d{2}\b/g)||[];const amount=text.match(/(\d+(?:[.,]\d{1,2})?)\s*(EUR|GBP|USD|CHF|JPY)\b/i);return {name:line?line.replace(/^[^:]+:\s*/,''):text.split(/\r?\n/).find(x=>x.trim())?.slice(0,100)||'',start:dates[0]||'',end:dates[1]||'',cost:amount?amount[1].replace(',','.'):'',currency:amount?.[2].toUpperCase()||'EUR',reference:text.match(/(?:référence|reference|booking|confirmation)\s*[:#]\s*([A-Z0-9-]+)/i)?.[1]||'',status:'à vérifier',notes:'Import texte à vérifier\n'+text.slice(0,6000)}}
function sharePreview(emergency=false){const t=trip();if(!t)return;$('#dialogContent').innerHTML=`<h2>${emergency?'Fiche d’urgence':'Aperçu du partage'}</h2><h3>${esc(t.name)}</h3><p>${esc(t.destination)} · ${date(t.start)} — ${date(t.end)}</p>${emergency?`<div class="notice emergency">${esc(t.emergency?.contact)}\n${esc(t.emergency?.phone)}\n${esc(t.emergency?.protocol)}</div>`:`<p>${related('days').length} étapes · Les références, documents du coffre, dépenses, contacts d’urgence et fichiers joints sont exclus.</p><label><input id="shareBookings" type="checkbox"> Inclure noms, lieux et dates des réservations</label><label><input id="shareJournal" type="checkbox"> Inclure les textes du journal (sans photo)</label>`}<p class="small">Ce fichier pourra être lu par toute personne à qui vous le transmettrez. Relisez avant partage.</p>${btn('Valider et télécharger',emergency?'emergency:export':'share:export','primary')}`;$('#dialog').showModal()}
function shareHTML(){const t=trip();if(!t)return;const withB=$('#shareBookings')?.checked,withJ=$('#shareJournal')?.checked;download('voyager-itineraire.html',htmlDocument(t.name,`<h1>${esc(t.name)}</h1><p>${esc(t.destination)} · ${date(t.start)} — ${date(t.end)}</p><ol>${itineraryItems().map(d=>`<li><strong>${date(d.day)} · ${esc(d.title)}</strong><p>${esc(d.notes)}</p></li>`).join('')}</ol>${withB?'<h2>Réservations</h2>'+related('bookings').map(b=>`<p>${esc(b.name)} · ${esc(b.place)} · ${date(b.start)}</p>`).join(''):''}${withJ?'<h2>Journal</h2>'+related('journal').map(j=>`<h3>${esc(j.title)}</h3><p>${esc(j.notes)}</p>`).join(''):''}`),'text/html');$('#dialog').close()}
function htmlDocument(title,body){return `<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{font:16px system-ui;max-width:800px;padding:25px;margin:auto;color:#152f40;line-height:1.6}p{white-space:pre-wrap}article{break-inside:avoid}img{max-width:100%;max-height:400px}h1{border-bottom:2px solid #0086a3;padding-bottom:15px}</style>${body}</html>`}
function sharePrint(){return htmlDocument('Journal VOYAGER',`<h1>${esc(trip()?.name)} — Journal</h1>${related('journal').map(j=>`<article><h2>${esc(j.title)}</h2><p>${date(j.day)} · ${esc(j.place)}</p><p>${esc(j.notes)}</p>${safeImage(j.photo)?`<img src="${safeImage(j.photo)}" alt="Souvenir">`:''}</article>`).join('')}<h2>Bilan</h2><p>${esc(trip()?.review||'')}</p>`)}
let vaultTimer;
function touchVault(){clearTimeout(vaultTimer);if(vaultUnlocked)vaultTimer=setTimeout(()=>{vaultUnlocked=null;if(tab==='vault')render()},300000)}
function navigate(next){if(!labels[next])return;tab=next;if(tab==='days'){subview='list';calendarMonth=trip()?.start?.slice(0,7)||now().slice(0,7)}render();window.scrollTo({top:0});}
async function handleAction(code){const [verb,kind,val]=code.split(':');
 if(verb==='packingmenu'||verb==='tripmenu'){const k=verb==='packingmenu'?'packing':'trips',x=db[k].find(x=>x.id===kind);if(!x)return;$('#dialogContent').innerHTML=`<h2>${esc(x.name)}</h2><div class="row">${btn('Modifier',`edit:${k}:${x.id}`)}${k==='trips'?btn('Dupliquer',`duplicate:${x.id}`)+btn('Archiver',`archive:${x.id}`):''}${btn('Supprimer',`del:${k}:${x.id}`,'danger')}</div>`;$('#dialog').showModal();return}
 if(verb==='goto')return navigate(kind);
 if(verb==='new'){if(kind!=='trips'&&!trip())return toast('Créez un voyage d’abord.');if(kind==='vault'&&!vaultUnlocked)return;editForm(kind);return}
 if(verb==='edit'){const x=db[kind]?.find(x=>x.id===val);if(x)editForm(kind,x);return}
 if(verb==='del'){if(!confirm('Supprimer cet élément ? Cette action ne concerne que la version indépendante.'))return;await historyWrite('Avant suppression');db[kind]=db[kind].filter(x=>x.id!==val);if(kind==='trips'){for(const k of [...COLLECTIONS,'points'].filter(k=>k!=='trips'))db[k]=(db[k]||[]).filter(x=>x.tripId!==val);tripId=db.trips[0]?.id||'';vaultUnlocked=null}if(kind==='bookings')db.expenses.forEach(e=>{if(e.bookingId===val)e.bookingId=''});if(save()){$('#dialog').close();render()}return}
 if(verb==='open'){tripId=kind;vaultUnlocked=null;return navigate('dashboard')}
 if(verb==='archive'){const t=db.trips.find(t=>t.id===kind);if(t){t.status='archivé';if(save()){$('#dialog').close();render()}}return}
 if(verb==='duplicate'){const source=db.trips.find(t=>t.id===kind);if(!source)return;const tid=id(),clone=structuredClone(source);Object.assign(clone,{id:tid,name:source.name+' (copie)',status:'préparation'});db.trips.push(clone);const bookingIds=new Map();for(const k of ['bookings','days','expenses','packing','journal','vault','points'])for(const child of [...(db[k]||[])].filter(x=>x.tripId===kind)){const x=structuredClone(child),newId=id();if(k==='bookings')bookingIds.set(x.id,newId);x.id=newId;x.tripId=tid;if(k==='expenses'&&x.bookingId)x.bookingId=bookingIds.get(x.bookingId)||'';if(k==='packing')x.ready=false;db[k].push(x)}tripId=tid;vaultUnlocked=null;if(save()){$('#dialog').close();render();toast('Voyage et contenus dupliqués.')}return}
 if(verb==='move'){const ordered=itineraryItems(),i=ordered.findIndex(x=>x.id===kind),j=i+Number(val);if(i<0||j<0||j>=ordered.length)return;[ordered[i],ordered[j]]=[ordered[j],ordered[i]];ordered.forEach((x,n)=>x.order=n+1);if(save())render();return}
 if(verb==='view'){subview=kind;render();return}
 if(verb==='month'){const [y,m]=calendarMonth.split('-').map(Number),d=new Date(y,m-1+Number(kind),1);calendarMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');render();return}
 if(verb==='filter'){if(kind==='save'){db.settings.savedTripFilter={searchQuery,tripFilter};if(save())toast('Critères mémorisés.')}else{tripFilter=kind;render()}return}
 if(verb==='customize'){customizing=!customizing;render();return}
 if(verb==='layout'){if(kind==='reset'){if(!confirm('Restaurer uniquement la disposition de l’accueil ? Vos voyages seront conservés.'))return;db.settings.layout=['next','preparation','shortcuts','budget','bookings','stats'];db.settings.sizes={next:'wide'}}else{const a=db.settings.layout,i=Number(kind),j=i+Number(val);if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]]}if(save())render();return}
 if(verb==='attachment'){const b=db.bookings.find(x=>x.id===kind);if(b?.attachment){const a=document.createElement('a');a.href=b.attachment;a.download=b.attachmentName||'confirmation';a.click()}return}
 if(verb==='unlock'){const pass=$('#vaultPass').value;if(pass.length<8)return alert('Choisissez au moins 8 caractères.');try{const docs=related('vault');let readable=0;for(const v of docs){try{await decrypt(v,pass);readable++}catch{}}if(docs.length&&!readable)throw Error();vaultUnlocked=pass;touchVault();render();if(docs.length)toast(readable+' document(s) accessibles avec cette phrase.')}catch{alert('Phrase incorrecte ou documents endommagés. Le coffre reste verrouillé.')}return}
 if(verb==='lock'){vaultUnlocked=null;clearTimeout(vaultTimer);render();return}
 if(verb==='openvault'){try{const v=db.vault.find(x=>x.id===kind);if(!vaultUnlocked)throw Error();const content=await decrypt(v,vaultUnlocked);if(!/^data:[^,]*;base64,[A-Za-z0-9+/=\s]*$/.test(content))throw Error();const a=document.createElement('a');a.href=content;a.download=v.filename||v.name;a.click();touchVault()}catch{alert('Déchiffrement impossible.')}return}
 if(verb==='theme'){const modes=['system','light','dark'];db.settings.theme=modes[(modes.indexOf(db.settings.theme)+1)%3];if(save())render();return}
 if(verb==='export'){if(kind==='json'){download('VOYAGER-sauvegarde-'+now()+'.json',JSON.stringify({...db,release:RELEASE,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Sauvegarde préparée pour téléchargement.')}else if(kind==='gpx')exportGPX();else if(kind==='ics')exportICS();else if(kind==='html')sharePreview();else download('voyager-'+kind+'.csv',csv(related(kind)),'text/csv');return}
 if(verb==='print'){const w=window.open('','_blank');if(!w)return alert('Autorisez la fenêtre d’impression.');w.document.write(sharePrint());w.document.close();w.onload=()=>w.print();return}
 if(verb==='share'){if(kind==='preview')sharePreview();else if(kind==='export')shareHTML();return}
 if(verb==='emergency'){if(kind==='preview')sharePreview(true);else if(kind==='export'){const e=trip().emergency||{};download('voyager-fiche-urgence.html',htmlDocument('Fiche d’urgence',`<h1>${esc(trip().name)} — Fiche d’urgence</h1><p>${date(trip().start)} — ${date(trip().end)}</p><h2>Contact de confiance</h2><p>${esc(e.contact)}\n${esc(e.phone)}</p><h2>Protocole convenu</h2><p>${esc(e.protocol)}</p>`),'text/html');$('#dialog').close()}return}
 if(verb==='bookingimport'){if(kind==='open')bookingImport();else{const text=$('#bookingText').value;if(!text.trim())return alert('Ajoutez le texte de la confirmation.');editForm('bookings',extractBooking(text));$('#dialogContent').insertAdjacentHTML('afterbegin','<div class="notice warn">Suggestions à relire. Vérifiez dates, devise, référence et montant avant enregistrement.</div>')}return}
 if(verb==='poi'){if(kind==='new'||kind==='edit'){const p=db.points.find(x=>x.id===val)||{};$('#dialogContent').innerHTML=`<h2>Point d’intérêt</h2><form id="poiForm" data-id="${esc(p.id||'')}"><div class="fields">${field('name','Nom','text',p.name||'','required')}${select('type','Type',['lieu','eau','bivouac','transport','ravitaillement','autre'],p.type||'lieu')}${field('lat','Latitude','number',p.lat??'','min="-90" max="90" step="any" required')}${field('lon','Longitude','number',p.lon??'','min="-180" max="180" step="any" required')}${area('notes','Source, date de vérification et notes',p.notes||'')}</div><p><button class="primary">Enregistrer</button></p></form>`;$('#dialog').showModal()}else if(kind==='open'){const p=db.points.find(x=>x.id===val);if(p)window.open(`https://www.openstreetmap.org/?mlat=${Number(p.lat)}&mlon=${Number(p.lon)}#map=14/${Number(p.lat)}/${Number(p.lon)}`,'_blank','noopener,noreferrer')}else if(kind==='del'&&confirm('Supprimer le point ?')){db.points=db.points.filter(x=>x.id!==val);if(save())render()}return}
 if(verb==='map'){if(kind==='clear'&&confirm('Retirer l’image de carte ?')){delete trip().mapImage;if(save())render()}return}
 if(verb==='clear'){if(kind==='gpx'){if(confirm('Supprimer la trace ?')){delete trip().gpx;delete trip().gpxSegments;if(save())render()}}else if(kind==='all'&&confirm('Effacer TOUS les voyages de cette version indépendante ?')&&confirm('Dernière confirmation. Une sauvegarde locale sera créée avant effacement.')){await historyWrite('Avant effacement');db=normalizeBackup(blank());tripId='';vaultUnlocked=null;if(save())render()}return}
 if(verb==='history'){try{const entries=(await historyRead()).sort((a,b)=>b.at.localeCompare(a.at));if(kind==='list'){$('#historyList').innerHTML=entries.map(e=>`<div class="item"><strong>${esc(e.label)}</strong><p>${new Date(e.at).toLocaleString('fr-FR')} · ${e.data.trips.length} voyage(s)</p>${btn('Télécharger JSON',`history:download:${e.id}`)}${btn('Restaurer',`history:restore:${e.id}`)}</div>`).join('')||'<p>Aucune version locale pour le moment.</p>'}else{const e=entries.find(x=>x.id===val);if(!e)return;if(kind==='download')download('voyager-historique-'+e.at.slice(0,10)+'.json',JSON.stringify(e.data,null,2),'application/json');else if(kind==='restore')await restore(new File([JSON.stringify(e.data)],'historique.json',{type:'application/json'}))}}catch(e){alert('Historique indisponible : '+e.message)}return}
 if(verb==='storage'){const result=await navigator.storage?.persist?.();toast(result?'Stockage persistant accordé.':'Persistance non accordée par ce navigateur. Exportez un JSON.');return}
 if(verb==='sw'){const r=await navigator.serviceWorker?.getRegistration();if(!r)return toast('Service worker indisponible.');if(kind==='check'){try{await r.update();toast(r.waiting?'Mise à jour prête à activer.':'Vérification effectuée. Aucune version en attente.')}catch{toast('Vérification impossible hors ligne.')}}else if(r.waiting){if(confirm('Recharger pour activer la mise à jour ? Les formulaires ouverts seront fermés.'))r.waiting.postMessage({type:'SKIP_WAITING'})}else toast('Aucune mise à jour en attente.');return}
}
function updateConnection(){const e=$('#connection');e.textContent=navigator.onLine?'Local · prêt à voyager':'Hors ligne';e.classList.toggle('offline',!navigator.onLine)}
document.addEventListener('click',async e=>{touchVault();const n=e.target.closest('[data-tab]');if(n){navigate(n.dataset.tab);return}const a=e.target.closest('[data-action]');if(a)try{await handleAction(a.dataset.action)}catch(err){alert('Action interrompue : '+err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='searchTrips'){searchQuery=e.target.value;const pos=e.target.selectionStart;render();const el=$('#searchTrips');el.focus();el.setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='tripSelect'){tripId=el.value;vaultUnlocked=null;render()}
 if(el.id==='themeSelect'){db.settings.theme=el.value;if(save())render()}
 if(el.id==='statusFilter'){tripFilter=el.value;render()}
 if(el.id==='calendarMonth'&&el.value){calendarMonth=el.value;render()}
 if(el.dataset.size){db.settings.sizes[el.dataset.size]=el.value;if(save())render()}
 if(el.dataset.ready){const p=db.packing.find(x=>x.id===el.dataset.ready);if(p){p.ready=el.checked;if(save())render()}}
 const f=el.files?.[0];if(!f)return;
 if(el.id==='restoreInput')await restore(f);if(el.id==='mergeInput')await mergeBackup(f);if(el.id==='gearInput')await importGear(f);if(el.id==='icsInput')await importICS(f);
 if(el.id==='gpxInput'){trip().gpx=parseGPX(await f.text());trip().gpxSegments=lastGPXSegments;if(save()){render();toast('GPX enregistré hors ligne.')}}
 if(el.id==='mapInput'){if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Format image non pris en charge');trip().mapImage=await fileData(f);if(save())render()}
 if(el.id==='bookingTextFile'){$('#bookingText').value=await f.text()}
 }catch(err){alert('Import interrompu : '+err.message)}finally{if(el.type==='file')el.value=''}});
document.addEventListener('submit',async e=>{const f=e.target;e.preventDefault();const v=new FormData(f);try{
 if(f.id==='tripBudgetForm'){trip().budget=Number(v.get('budget'));if(!Number.isFinite(trip().budget)||trip().budget<0)throw Error('Budget invalide');if(save()){render();toast('Enveloppe enregistrée.')}return}
 if(f.id==='ratesForm'){const candidate={...db.rates},meta={...db.rateMeta};for(const [c,value]of v){if(c.endsWith('_date')||c.endsWith('_source')||!value)continue;const n=Number(value),date=v.get(c+'_date'),source=String(v.get(c+'_source')||'').trim();if(!Number.isFinite(n)||n<=0||!date||!source)throw Error('Renseignez un taux positif, une date et une source pour '+c);candidate[c]=n;meta[c]={date,source}}db.rates=candidate;db.rates.EUR=1;db.rateMeta=meta;if(save()){render();toast('Taux datés enregistrés.')}return}
 if(f.id==='currencyForm'){const code=String(v.get('code')).toUpperCase();try{new Intl.NumberFormat('fr',{style:'currency',currency:code}).format(0)}catch{throw Error('Code ISO invalide')}if(!/^[A-Z]{3}$/.test(code)||code==='EUR')throw Error('Code non pris en charge');db.rates[code]||=1;if(save())render();return}
 if(f.id==='scenarioForm'){db.settings.scenarioExtra=Number(v.get('extra'));db.settings.scenarioMargin=Number(v.get('margin'));if(save())render();return}
 if(f.id==='reviewForm'){trip().review=String(v.get('review'));if(save()){render();toast('Bilan enregistré.')}return}
 if(f.id==='emergencyForm'){trip().emergency=Object.fromEntries(v);if(save())toast('Fiche enregistrée.');return}
 if(f.id==='poiForm'){const p={id:f.dataset.id||id(),tripId,...Object.fromEntries(v)};p.lat=Number(p.lat);p.lon=Number(p.lon);if(!Number.isFinite(p.lat)||!Number.isFinite(p.lon)||Math.abs(p.lat)>90||Math.abs(p.lon)>180)throw Error('Coordonnées invalides');const i=db.points.findIndex(x=>x.id===p.id);if(i>=0)db.points[i]=p;else db.points.push(p);if(save()){$('#dialog').close();render()}return}
 if(f.id!=='entityForm')return;const kind=f.dataset.kind,existing=db[kind].find(x=>x.id===f.dataset.id),obj=existing?structuredClone(existing):{id:id(),tripId};for(const [k,value]of v)if(!(value instanceof File))obj[k]=value;
 if(kind==='trips'){if(obj.start&&obj.end&&obj.end<obj.start)throw Error('Le retour précède le départ');if(v.get('isTemplate'))obj.status='modèle';delete obj.isTemplate;if(obj.budget!==''){obj.budget=Number(obj.budget);if(!Number.isFinite(obj.budget)||obj.budget<0)throw Error('Budget invalide')}}
 if(kind==='days'){if(!existing)obj.order=related('days').length+1;if(obj.duration&&!obj.durationSource?.trim())throw Error('Précisez la source de la durée ou laissez-la vide')}
 if(kind==='expenses'){obj.amount=Number(obj.amount);if(!Number.isFinite(obj.amount)||obj.amount<0)throw Error('Montant invalide');if(obj.bookingId&&!related('bookings').some(b=>b.id===obj.bookingId))throw Error('Réservation liée invalide')}
 if(kind==='bookings'){obj.cost=Number(obj.cost||0);if(!Number.isFinite(obj.cost)||obj.cost<0)throw Error('Coût invalide');if(obj.end&&obj.start&&obj.end<obj.start)throw Error('Date de fin antérieure au début');const a=v.get('attachmentFile');if(a?.size){if(!['application/pdf','image/png','image/jpeg','image/webp','text/plain'].includes(a.type))throw Error('Justificatif : PDF, PNG, JPEG, WEBP ou texte uniquement');obj.attachment=await fileData(a);obj.attachmentName=a.name}}
 if(kind==='packing'){obj.qty=Number(obj.qty);obj.grams=Number(obj.grams);if(!Number.isFinite(obj.qty)||obj.qty<1||!Number.isInteger(obj.qty)||!Number.isFinite(obj.grams)||obj.grams<0)throw Error('Quantité entière et poids positif requis');obj.weightUnknown=false}
 if(kind==='journal'){const photo=v.get('photoFile');if(photo?.size){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(photo.type))throw Error('Photo JPEG, PNG, WEBP ou GIF requise');obj.photo=await fileData(photo)}}
 if(kind==='vault'){if(!vaultUnlocked)throw Error('Coffre verrouillé');const secret=v.get('secretFile');if(!secret?.size)throw Error('Choisissez un fichier');Object.assign(obj,await encrypt(await fileData(secret),vaultUnlocked));obj.filename=secret.name;touchVault()}
 if(existing)Object.assign(existing,obj);else db[kind].push(obj);if(save()){if(kind==='trips')tripId=obj.id;$('#dialog').close();render();toast('Enregistré.')}else render();
 }catch(err){alert('Enregistrement refusé : '+err.message)}});
$('#closeDialog').addEventListener('click',()=>$('#dialog').close());$('#theme').addEventListener('click',()=>handleAction('theme:toggle'));addEventListener('online',updateConnection);addEventListener('offline',updateConnection);document.addEventListener('visibilitychange',()=>{if(document.hidden){vaultUnlocked=null;clearTimeout(vaultTimer);if(tab==='vault')render()}});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(db.settings.theme==='system')render()});
if(db.settings.savedTripFilter)({searchQuery,tripFilter}=db.settings.savedTripFilter);
if('serviceWorker'in navigator){let reloadPending=false;navigator.serviceWorker.register('./sw.js').then(r=>{r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('Mise à jour disponible dans les paramètres.')})})}).catch(()=>toast('Cache hors ligne indisponible.'));navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloadPending){reloadPending=true;location.reload()}})}render();
